// 特定技能2号評価試験テキスト（グランドハンドリング vol.1 / vol.2）準拠の問題バンク。各問の src に出典（章・ページ）を記載。
// Questions are original paraphrases written against the official textbook; correct answers are grounded in the cited pages.
export const QUIZ_BANK_S2 = [
  {"id": "S2R01", "topic": "s2_ramp", "level": 2, "src": "SSW2テキスト 1-1 (p.3)", "qJa": "航空機の運航に求められる4つの要素のうち、「快適性」に対応する取り組みとしてテキストに示されているものはどれか？", "qVi": "Trong 4 yếu tố của khai thác tàu bay, biện pháp nào được giáo trình nêu cho \"tính thoải mái\" (快適性)?", "qEn": "Among the four requirements of aircraft operation, which measure does the textbook give for \"comfort\"?", "optsJa": ["決められた時間内での作業の確実な実施", "機内の環境を良く保つための清掃", "搭載重量と重心位置の適切な管理", "排ガスや騒音など環境への対策"], "optsVi": ["Thực hiện chắc chắn công việc trong thời gian quy định", "Dọn vệ sinh để giữ môi trường trong khoang tốt", "Quản lý trọng lượng chất xếp và vị trí trọng tâm", "Biện pháp đối với khí thải và tiếng ồn"], "optsEn": ["Reliably finishing tasks within the set time", "Cleaning to keep the cabin environment good", "Managing loaded weight and center of gravity", "Measures against exhaust gas and noise"], "ans": 1, "expJa": "快適性については、機内を良い環境に保つために清掃などを行うとされている。時間内の作業は定時性、重量・重心管理は安全性、排ガス・騒音対策は社会性に当たる。", "expVi": "Với tính thoải mái, giáo trình nêu việc dọn vệ sinh để giữ môi trường khoang tốt. Làm đúng giờ thuộc tính đúng giờ (定時性), quản lý trọng lượng/trọng tâm thuộc an toàn, khí thải/tiếng ồn thuộc tính xã hội (社会性).", "expEn": "For comfort, the textbook names cleaning to keep the cabin pleasant. On-time work is punctuality, weight and CG control is safety, and exhaust/noise measures are social responsibility."},
  {"id": "S2R02", "topic": "s2_ramp", "level": 2, "src": "SSW2テキスト 1-1 (p.4)", "qJa": "グランドハンドリング専門の会社が設立された理由として、テキストに示されているものはどれか？", "qVi": "Lý do thành lập các công ty chuyên về handling mặt đất (グランドハンドリング) theo giáo trình là gì?", "qEn": "According to the textbook, why were specialized ground handling companies established?", "optsJa": ["航空会社が整備作業を自社で行うことを法律で禁止されたため", "外国航空会社の地上支援を全面的に引き受ける義務が生じたため", "空港の数が急増し、整備会社の人員が大幅に不足したため", "質の違う整備と地上支援を同じ組織に置くと問題があったため"], "optsVi": ["Hãng hàng không bị luật cấm tự thực hiện công việc bảo dưỡng của mình", "Phát sinh nghĩa vụ nhận toàn bộ hỗ trợ mặt đất cho các hãng nước ngoài", "Số sân bay tăng nhanh khiến công ty bảo dưỡng thiếu người trầm trọng", "Đặt bảo dưỡng và hỗ trợ mặt đất khác bản chất chung một tổ chức gây vấn đề"], "optsEn": ["Airlines were prohibited by law from doing their own maintenance work", "An obligation arose to take on all of the foreign airlines' ground support", "Airports increased rapidly and maintenance firms badly lacked staff", "Keeping maintenance and ground support, different in nature, in one body caused problems"], "ans": 3, "expJa": "整備と空港での地上支援という性質の異なる業務を一つの組織で扱うことに問題があり、旅客・貨物の増加に備えて地上支援部門を強化する必要もあったため、専門会社が作られた。", "expVi": "Vì việc gộp hai mảng khác bản chất là bảo dưỡng và hỗ trợ mặt đất trong một tổ chức có vấn đề, đồng thời cần tăng cường bộ phận hỗ trợ mặt đất trước lượng khách và hàng tăng, nên công ty chuyên môn được lập ra.", "expEn": "Handling maintenance and airport ground support, two different kinds of work, in one organization was problematic, and ground support needed strengthening for growing traffic, so dedicated companies were set up."},
  {"id": "S2R03", "topic": "s2_ramp", "level": 2, "src": "SSW2テキスト 1-1 (p.4)", "qJa": "客室のトイレット・システムについて、最近一般的とされている方式はどれか？", "qVi": "Về hệ thống nhà vệ sinh khoang khách, phương thức nào được cho là phổ biến gần đây?", "qEn": "Which cabin toilet system does the textbook describe as common today?", "optsJa": ["バキューム式集中タンク方式", "汚水タンクを都度機外へ運び出す方式", "各トイレに個別の循環式タンクを置く方式", "汚水を機内で化学処理して保管する方式"], "optsVi": ["Kiểu bồn tập trung hút chân không", "Kiểu mỗi lần mang bồn nước thải ra ngoài", "Kiểu mỗi buồng có bồn tuần hoàn riêng", "Kiểu xử lý hóa học nước thải rồi giữ trên máy bay"], "optsEn": ["A vacuum-type centralized tank system", "Carrying the waste tank off each time", "A separate recirculating tank per toilet", "Chemically treating waste on board"], "ans": 0, "expJa": "プロペラ機の頃は汚水のタンクごと機外へ運んでおり、ジェット旅客機で循環式タンクになった。現在ではバキューム式の集中タンク方式が一般的とされている。", "expVi": "Thời máy bay cánh quạt phải mang bồn thải ra ngoài, đến máy bay phản lực thì dùng bồn tuần hoàn. Hiện nay kiểu bồn tập trung hút chân không là phổ biến.", "expEn": "In the propeller era waste tanks were carried out; jet airliners then used recirculating tanks. Today the vacuum central tank system is common."},
  {"id": "S2R04", "topic": "s2_ramp", "level": 2, "src": "SSW2テキスト 2-1 (p.6)", "qJa": "誘導作業（ランプ・イン／アウト作業）が、ほかのグランドハンドリング業務と大きく異なる点はどれか？", "qVi": "Điểm khác biệt lớn của công việc dẫn đường (ランプ・イン／アウト) so với các nghiệp vụ handling khác là gì?", "qEn": "What mainly distinguishes guidance work (ramp-in/out) from other ground handling tasks?", "optsJa": ["旅客と直接接すること", "必ず夜間に行われること", "航空機の移動を伴うこと", "動力付き器材を使わないこと"], "optsVi": ["Tiếp xúc trực tiếp với hành khách", "Luôn được thực hiện vào ban đêm", "Có sự di chuyển của tàu bay", "Không sử dụng thiết bị có động cơ"], "optsEn": ["It involves direct contact with passengers", "It is always carried out at night", "It involves aircraft movement", "It uses no powered equipment at all"], "ans": 2, "expJa": "誘導作業の最大の特徴は、航空機の移動が伴う点にある。マーシャリング、トーイング、プッシュバック、ブレーキマン、ウォッチマンの作業に分かれる。", "expVi": "Đặc trưng lớn nhất của công việc dẫn đường là có sự di chuyển của tàu bay. Nó gồm marshalling, kéo (トーイング), đẩy lùi (プッシュバック), người phanh (ブレーキマン) và người canh (ウォッチマン).", "expEn": "Its key feature is that the aircraft moves. It is divided into marshalling, towing, pushback, brakeman and watchman work."},
  {"id": "S2R05", "topic": "s2_ramp", "level": 2, "src": "SSW2テキスト 2-2-1 (p.7)", "qJa": "一部の空港で導入されている VDGS（Visual Docking Guidance System）の説明として正しいものはどれか？", "qVi": "Mô tả nào đúng về VDGS (Visual Docking Guidance System) được dùng ở một số sân bay?", "qEn": "Which description of the VDGS (Visual Docking Guidance System) used at some airports is correct?", "optsJa": ["マーシャラーの手信号を撮影して管制塔へ送信する", "赤外線レーザーで機体を計測し、表示板で指示する", "地上に埋め込んだ灯火でタキシング経路を照らす", "停止位置までの距離を無線音声でパイロットに伝える"], "optsVi": ["Quay hình tín hiệu tay của marshaller rồi gửi lên đài", "Đo tàu bay bằng laser hồng ngoại, chỉ dẫn qua bảng LED", "Chiếu sáng đường lăn bằng đèn gắn chìm dưới đất", "Báo khoảng cách đến vị trí dừng qua radio cho phi công"], "optsEn": ["Films the marshaller's hand signals and sends them to the tower", "Measures the aircraft by infrared laser and instructs via an LED board", "Lights the taxi route using lamps embedded in the ground", "Tells the pilot the distance to the stop line by radio voice"], "ans": 1, "expJa": "VDGS は赤外線レーザーで航空機を捕捉して外形やノーズまでの距離などを自動計測し機種を識別する。その後、LED の電光掲示板で左右方向や停止位置までの距離、停止を指示する。", "expVi": "VDGS bắt tàu bay bằng laser hồng ngoại, tự động đo hình dạng, khoảng cách đến mũi để nhận dạng loại máy bay. Sau đó bảng LED chỉ hướng trái/phải, khoảng cách đến vị trí dừng và lệnh dừng.", "expEn": "VDGS captures the aircraft with an infrared laser, automatically measures its shape and nose distance, and identifies the type. It then shows left/right, distance to stop and stop on an LED board."},
  {"id": "S2R06", "topic": "s2_ramp", "level": 2, "src": "SSW2テキスト 2-2-2 (p.8)", "qJa": "マーシャリングにおける責任について、テキストの記述として正しいものはどれか？", "qVi": "Về trách nhiệm trong marshalling, nội dung nào đúng theo giáo trình?", "qEn": "Regarding responsibility in marshalling, which statement matches the textbook?", "optsJa": ["安全監視を含む地上誘導全体の作業責任はマーシャラーにある", "タキシング中の安全に対する最終責任はマーシャラーにある", "機体がシグナルに反して停止した場合の責任はマーシャラーにある", "マーシャリング中の作業責任はすべて管制官が負う"], "optsVi": ["Trách nhiệm toàn bộ việc dẫn đường mặt đất, gồm giám sát an toàn, thuộc marshaller", "Trách nhiệm cuối cùng về an toàn khi tàu bay lăn bánh thuộc về marshaller", "Khi tàu bay dừng trái với tín hiệu, trách nhiệm thuộc về marshaller", "Mọi trách nhiệm công việc trong khi marshalling đều do kiểm soát viên chịu"], "optsEn": ["The marshaller holds work responsibility for all ground guidance, incl. safety watch", "The marshaller holds final responsibility for aircraft safety during taxiing", "If the aircraft stops contrary to the signals, the marshaller is responsible", "Air traffic controllers bear all of the work responsibility during marshalling"], "ans": 0, "expJa": "タキシング中の安全の最終責任は操縦するパイロットにあり、シグナルに反した行動の責任もキャプテンが負う。一方、シグナルで機体の動きを指示する立場上、安全監視も含めた地上誘導の作業全体についてはマーシャラーが責任を負う。", "expVi": "Trách nhiệm cuối cùng về an toàn khi lăn thuộc phi công, và khi máy bay hành động trái tín hiệu thì cơ trưởng chịu trách nhiệm. Nhưng vì marshaller ra tín hiệu điều khiển chuyển động, trách nhiệm công việc dẫn đường mặt đất (kể cả giám sát an toàn) thuộc marshaller.", "expEn": "Final safety responsibility while taxiing lies with the pilot, and the captain is responsible if the aircraft deviates from the signals. But since the marshaller directs the movement, work responsibility for the whole ground guidance, including safety watch, is the marshaller's."},
  {"id": "S2R07", "topic": "s2_ramp", "level": 2, "src": "SSW2テキスト 2-2-3 (p.8)", "qJa": "ランプエリアで航空機が交通の最優先とされる理由として、テキストに挙げられていないもの（誤っているもの）はどれか？", "qVi": "Lý do nào KHÔNG được giáo trình nêu (KHÔNG đúng) cho việc tàu bay được ưu tiên giao thông cao nhất trong khu sân đỗ?", "qEn": "Which is NOT correct as a reason given in the textbook for aircraft having top traffic priority on the ramp?", "optsJa": ["機敏に動けず視界が悪いから", "多量の可燃性物資を積むから", "機体そのものが高価だから", "旅客が搭乗しているから"], "optsVi": ["Vì kém linh hoạt và tầm nhìn kém", "Vì chở lượng lớn chất dễ cháy", "Vì bản thân tàu bay rất đắt tiền", "Vì luôn có hành khách trên máy bay"], "optsEn": ["Because it cannot move nimbly and sees poorly", "Because it carries large amounts of flammables", "Because the aircraft itself is expensive", "Because passengers are always on board"], "ans": 3, "expJa": "テキストが挙げる理由は、機体の大きさ・形状から素早く動けず視界も悪いこと、多量の可燃性物資を積むこと、高価であることである。旅客の搭乗は理由として示されていない。", "expVi": "Giáo trình nêu các lý do: do kích thước, hình dạng nên không di chuyển nhanh và tầm nhìn kém, chở nhiều chất dễ cháy, và đắt tiền. Việc có hành khách không được nêu làm lý do.", "expEn": "The textbook cites that the aircraft cannot move nimbly and has poor visibility due to its size and shape, carries much flammable material, and is expensive. Passengers on board are not given as a reason."},
  {"id": "S2R08", "topic": "s2_ramp", "level": 2, "src": "SSW2テキスト 2-2-3 (p.9)", "qJa": "ボーイング787の例で、操縦席から前方の地上障害物を確認できるのは、前方何m以上離れた場所からか？", "qVi": "Với ví dụ Boeing 787, từ ghế lái chỉ nhìn thấy chướng ngại vật trên mặt đất phía trước khi cách bao nhiêu m trở lên?", "qEn": "In the Boeing 787 example, ground obstacles ahead can be seen from the cockpit only when at least how far ahead?", "optsJa": ["12m", "7.5m", "15m", "40m"], "optsVi": ["12m", "7,5m", "15m", "40m"], "optsEn": ["12 m", "7.5 m", "15 m", "40 m"], "ans": 2, "expJa": "B787の例では、地上の障害物が操縦席から前方15m未満にあると見えない。12mは機長席から右側を見た場合の数値である。", "expVi": "Theo ví dụ B787, từ ghế lái không thấy được chướng ngại vật mặt đất nếu nó cách chưa đến 15m phía trước. 12m là số liệu khi nhìn sang phía phải từ ghế cơ trưởng.", "expEn": "For the B787, ground obstacles cannot be seen from the cockpit unless they are 15 m or more ahead. 12 m applies to the right side as seen from the captain's seat."},
  {"id": "S2R09", "topic": "s2_ramp", "level": 2, "src": "SSW2テキスト 2-2-3 (p.10)", "qJa": "マーシャラーが誘導しないとき、タキシング中の機体の前方何mの範囲に車両や障害物があってはならないとされているか？", "qVi": "Khi không có marshaller dẫn đường, trong phạm vi bao nhiêu m phía trước tàu bay đang lăn không được có xe hay chướng ngại vật?", "qEn": "Without marshaller guidance, within how many meters ahead of a taxiing aircraft must there be no vehicles or obstacles?", "optsJa": ["15m", "40m", "25m", "53m"], "optsVi": ["15m", "40m", "25m", "53m"], "optsEn": ["15 m", "40 m", "25 m", "53 m"], "ans": 1, "expJa": "操縦席からの死角が大きいため、マーシャラーが誘導しないときは、タキシングする機体の前方40mの範囲に車両や障害物を置いてはならないとされている。", "expVi": "Do điểm mù từ buồng lái lớn, khi không có marshaller thì trong vòng 40m phía trước tàu bay đang lăn không được có xe cộ hay chướng ngại vật.", "expEn": "Because cockpit blind spots are large, when no marshaller guides the aircraft there must be no vehicles or obstacles within 40 m ahead of it while taxiing."},
  {"id": "S2R10", "topic": "s2_ramp", "level": 2, "src": "SSW2テキスト 2-2-3 (p.11)", "qJa": "ジェット機のエンジン・ブラスト（排気）の危険について、テキストの記述として正しいものはどれか？", "qVi": "Về nguy hiểm của luồng xả động cơ (ブラスト) máy bay phản lực, nội dung nào đúng theo giáo trình?", "qEn": "Regarding the danger of jet engine blast (exhaust), which statement matches the textbook?", "optsJa": ["通常は風速が問題で、25m/sは台風なみである", "通常は温度が問題とされ、風速は問題にならない", "影響範囲はエンジン後方の5m以内に限られる", "アイドル時のブラストには危険性がまったくない"], "optsVi": ["Thường vấn đề là tốc độ gió; 25m/s ngang bão", "Thường vấn đề là nhiệt độ, tốc độ gió không đáng kể", "Phạm vi ảnh hưởng chỉ trong 5m phía sau động cơ", "Luồng xả ở chế độ không tải không có nguy hiểm"], "optsEn": ["Wind speed is the usual issue; 25 m/s is typhoon-like", "Temperature is usually the issue; wind speed is not", "The effect is limited to within 5 m behind the engine", "Blast at idle power carries no danger at all"], "ans": 0, "expJa": "ブラストは温度と風速の両面で影響するが、一般に問題視されるのは風速の方である。風速25m/sのブラストは台風なみで、不意をつかれると非常に危険である。", "expVi": "Ảnh hưởng của luồng xả gồm nhiệt độ và tốc độ gió, nhưng thường tốc độ gió mới là vấn đề. Luồng xả 25m/s mạnh như bão, rất nguy hiểm nếu bị bất ngờ.", "expEn": "Blast effects include temperature and wind speed, but wind speed is usually the concern. A 25 m/s blast is typhoon-strength and very dangerous if it catches you off guard."},
  {"id": "S2R11", "topic": "s2_ramp", "level": 2, "src": "SSW2テキスト 2-2-3 (p.11)", "qJa": "平均的な大きさの人がエンジン入口の直前で受ける吸引力として、テキストに示されている数値の組み合わせはどれか？", "qVi": "Lực hút mà một người có vóc dáng trung bình phải chịu ngay trước cửa hút động cơ, theo giáo trình là tổ hợp nào?", "qEn": "Which pair of values does the textbook give for the suction force on an average-sized person right in front of an engine inlet?", "optsJa": ["離陸時 約140kg、アイドル時 約460kg", "離陸時 約460kg、アイドル時 約240kg", "離陸時 約250kg、アイドル時 約140kg", "離陸時 約460kg、アイドル時 約140kg"], "optsVi": ["Khi cất cánh ~140kg, không tải ~460kg", "Khi cất cánh ~460kg, không tải ~240kg", "Khi cất cánh ~250kg, không tải ~140kg", "Khi cất cánh ~460kg, không tải ~140kg"], "optsEn": ["Takeoff about 140 kg, idle about 460 kg", "Takeoff about 460 kg, idle about 240 kg", "Takeoff about 250 kg, idle about 140 kg", "Takeoff about 460 kg, idle about 140 kg"], "ans": 3, "expJa": "エンジン入口直前で受ける力は、離陸時に約460kg、アイドルの状態でも約140kgほどになる。エンジンが小さくても吸い込む力は大型と同程度なので油断は禁物である。", "expVi": "Lực tác động ngay trước cửa hút đạt khoảng 460kg khi cất cánh và vẫn khoảng 140kg khi không tải. Động cơ nhỏ cũng có lực hút không kém động cơ lớn.", "expEn": "The force right in front of the inlet reaches about 460 kg at takeoff and still about 140 kg at idle. Even small engines pull as strongly as large ones."},
  {"id": "S2R12", "topic": "s2_ramp", "level": 2, "src": "SSW2テキスト 2-2-4 (p.12)", "qJa": "航空機誘導作業で使用する合図具について、テキストの記述として正しいものはどれか？", "qVi": "Về dụng cụ ra hiệu dùng khi dẫn đường tàu bay, nội dung nào đúng theo giáo trình?", "qEn": "Regarding the signaling tools for aircraft guidance, which statement matches the textbook?", "optsJa": ["白色のパドルを使い、夜間は懐中電灯を使う", "色の指定はなく、誘導員が見やすい物を選ぶ", "橙色の蛍光パドル等、夜間は発光指示棒", "昼夜を問わず常に発光する指示棒だけを使う"], "optsVi": ["Dùng paddle màu trắng; ban đêm dùng đèn pin", "Không quy định màu, người dẫn tự chọn loại dễ nhìn", "Paddle cam huỳnh quang; ban đêm dùng gậy phát sáng", "Dùng duy nhất gậy phát sáng cả ngày lẫn đêm"], "optsEn": ["Use white paddles by day and flashlights at night", "No color is set; the marshaller picks what is visible", "Orange fluorescent paddles etc.; lighted wands at night", "Always use only lighted wands, whether day or night"], "ans": 2, "expJa": "合図具は橙色で蛍光着色された指示棒・パドル・グローブとし、夜間や視界不良時は発光する指示棒を使う。シグナル自体は ICAO で規定されたものを使うのが原則である。", "expVi": "Khi ra hiệu phải dùng gậy, paddle hoặc găng tay màu cam huỳnh quang; ban đêm hay khi tầm nhìn kém dùng gậy phát sáng. Về nguyên tắc, tín hiệu dùng loại do ICAO quy định.", "expEn": "Signals use orange fluorescent wands, paddles or gloves, and illuminated wands at night or in poor visibility. In principle, the ICAO-defined signals are used."},
  {"id": "S2R13", "topic": "s2_ramp", "level": 2, "src": "SSW2テキスト 2-2-4 (p.13)", "qJa": "ICAO方式の「標準停止」のシグナルの説明として正しいものはどれか？", "qVi": "Mô tả nào đúng về tín hiệu \"dừng tiêu chuẩn\" (標準停止) theo kiểu ICAO?", "qEn": "Which description of the ICAO \"normal stop\" signal is correct?", "optsJa": ["停止線の約15m手前から両腕を頭上で素早く左右に振る", "停止線に達したら両腕を水平より45°下げて保持する", "停止線の約5m手前で右手で敬礼の仕草をする", "約5m手前で腕を真横に伸ばし、停止線でパドルを交差"], "optsVi": ["Từ ~15m trước vạch dừng, vẫy nhanh hai tay trên đầu", "Tới vạch dừng thì giữ hai tay hạ 45° dưới phương ngang", "Cách vạch dừng khoảng 5m thì giơ tay phải lên chào", "Cách vạch ~5m dang tay ngang, tới vạch bắt chéo paddle"], "optsEn": ["From about 15 m before the line, wave both arms quickly overhead", "At the line, hold both arms 45 degrees below horizontal", "About 5 m before the line, give a salute with the right hand", "Arms out sideways ~5 m before the line, paddles crossed at it"], "ans": 3, "expJa": "標準停止では、停止線の約5m手前で腕を真横に伸ばし、近づくにつれて腕を上げていき、停止線でパドルを交差させる。頭上で素早く振るのは急停止、45°下げて保持するのは待機である。", "expVi": "Dừng tiêu chuẩn: cách vạch dừng khoảng 5m thì dang tay ngang, càng gần càng nâng tay lên, đến vạch thì bắt chéo paddle. Vẫy nhanh trên đầu là dừng khẩn cấp, giữ tay hạ 45° là chờ.", "expEn": "For a normal stop, extend the arms sideways about 5 m before the line, raise them as the aircraft nears, and cross the paddles at the line. Quick overhead waving is emergency stop; holding 45 degrees down is hold."},
  {"id": "S2R14", "topic": "s2_ramp", "level": 2, "src": "SSW2テキスト 2-2-4 (p.14)", "qJa": "「ブレーキ・セット（ブレーキを掛ける）」のシグナルとして正しいものはどれか？", "qVi": "Tín hiệu nào đúng cho \"cài phanh\" (ブレーキ・セット)?", "qEn": "Which is the correct signal for \"brake set\"?", "optsJa": ["開いた右手を肩の上に上げ、確認後に拳を握る", "両腕を頭上に一杯に伸ばし、パドル同士を突き合わせる", "右手の握り拳を肩の上に上げ、確認後に手を開く", "右手を首の前で左から右へ水平に動かす"], "optsVi": ["Giơ tay phải mở trên vai, xác nhận xong thì nắm lại", "Duỗi hai tay hết cỡ trên đầu, chạm hai paddle vào nhau", "Nắm tay phải giơ trên vai, xác nhận xong thì mở tay", "Đưa tay phải ngang trước cổ từ trái sang phải"], "optsEn": ["Raise open right hand above shoulder, then close a fist after confirmation", "Stretch both arms overhead and bring the paddles together", "Raise right fist above shoulder, then open the hand after confirmation", "Move the right hand across the throat from left to right"], "ans": 2, "expJa": "ブレーキ・セットでは、右手を握ったまま肩より少し上に上げ、乗務員と目が合ったことを確かめてから手を開く。逆に、開いた手を握るのはブレーキ・リリースである。", "expVi": "Cài phanh: giơ nắm tay phải ngang trên vai, xác nhận giao tiếp bằng mắt với tổ bay rồi mở bàn tay. Ngược lại, từ tay mở rồi nắm lại là nhả phanh (ブレーキ・リリース).", "expEn": "Brake set: raise the closed right fist just above the shoulder, confirm eye contact with the flight crew, then open the hand. Closing an open hand is brake release."},
  {"id": "S2R15", "topic": "s2_ramp", "level": 2, "src": "SSW2テキスト 2-3-1 (p.16)", "qJa": "トーイング時のトーイングマンと管制官との交信について、誤っているものはどれか？", "qVi": "Về liên lạc giữa người kéo (トーイングマン) và kiểm soát viên khi kéo tàu bay, nội dung nào KHÔNG đúng?", "qEn": "Regarding communication between the towing operator and the controller, which statement is NOT correct?", "optsJa": ["交信の語尾にはコールサインを付ける", "聞き取れていれば復唱は省略してよい", "呼び出しがあれば速やかに応答する", "交信はできる限り簡潔明瞭に行う"], "optsVi": ["Thêm hô hiệu (コールサイン) vào cuối câu liên lạc", "Nghe rõ chỉ thị thì có thể bỏ việc nhắc lại", "Khi được gọi thì phải trả lời nhanh chóng", "Nội dung liên lạc phải ngắn gọn và rõ ràng"], "optsEn": ["Add the call sign at the end of each transmission", "Read-back may be skipped if clearly heard", "Answer promptly whenever you are called", "Keep every transmission brief and clear"], "ans": 1, "expJa": "交信は簡潔明瞭に行い、語尾にコールサインを付け、管制官の指示は必ず声に出して繰り返し、呼び出しには速やかに応答する。経路を間違えると地上が大混乱するため、復唱は省略できない。", "expVi": "Liên lạc phải ngắn gọn rõ ràng, cuối câu có hô hiệu, luôn nhắc lại thành tiếng chỉ thị của kiểm soát viên và trả lời ngay khi được gọi. Sai đường kéo sẽ gây hỗn loạn mặt đất nên không được bỏ việc nhắc lại.", "expEn": "Transmissions must be brief and clear, end with the call sign, always repeat the controller's instructions aloud, and answer calls promptly. A wrong route causes chaos on the ground, so read-back cannot be skipped."},
  {"id": "S2R16", "topic": "s2_ramp", "level": 2, "src": "SSW2テキスト 2-3-2 (p.16-17)", "qJa": "トーイング開始前に、トーイング・レバーをトーイング・ポジションにしてステアリング・ロック・アウト・ピンを取り付ける目的はどれか？", "qVi": "Trước khi kéo, mục đích đặt cần kéo (トーイング・レバー) ở vị trí kéo và lắp chốt khóa lái (ステアリング・ロック・アウト・ピン) là gì?", "qEn": "Before towing, what is the purpose of setting the towing lever to the towing position and installing the steering lockout pin?", "optsJa": ["トーイング・レバーをその位置に保持するため", "ランディング・ギアが格納されるのを防ぐため", "パーキング・ブレーキを確実に固定するため", "トーバーをトラクターに確実に連結するため"], "optsVi": ["Để giữ cần kéo ở vị trí kéo", "Để ngăn càng đáp bị thu lên", "Để cố định chắc chắn phanh đỗ", "Để nối thanh kéo với xe kéo"], "optsEn": ["To hold the towing lever in position", "To prevent the landing gear from retracting", "To lock the parking brake firmly", "To connect the towbar to the tractor"], "ans": 0, "expJa": "このピンの役割は、トーイング・レバーがトーイング位置から動かないよう保つことで、ステアリング系統の油圧はロック・アウトされて、機種ごとに決まった角度まで旋回できる。", "expVi": "Chốt này để giữ cần kéo ở vị trí kéo; áp suất thủy lực vào hệ thống lái bị khóa và tàu bay có thể quay tới góc quy định theo từng loại.", "expEn": "The pin holds the towing lever in the towing position; hydraulic pressure to the steering system is locked out, allowing turns up to a type-specific angle."},
  {"id": "S2R17", "topic": "s2_ramp", "level": 2, "src": "SSW2テキスト 2-3-2 (p.18)", "qJa": "トーイング前の準備作業でいう「サークル・チェック」の内容として正しいものはどれか？", "qVi": "\"Kiểm tra vòng quanh\" (サークル・チェック) trong công tác chuẩn bị trước khi kéo là gì?", "qEn": "What does the \"circle check\" in pre-towing preparation mean?", "optsJa": ["トーイング経路を一周して事前に障害物を確認する", "パネル・ドアの閉鎖など機体の360度を確認する", "トラクターの周囲を一周して車両の状態を点検する", "管制官とトーイング経路を順番に読み合わせる"], "optsVi": ["Đi một vòng tuyến đường kéo để kiểm tra chướng ngại", "Kiểm tra 360 độ tàu bay như việc đóng các panel, cửa", "Đi quanh xe kéo một vòng để kiểm tra phương tiện", "Đọc đối chiếu tuyến đường theo thứ tự với kiểm soát viên"], "optsEn": ["Walking the whole towing route in advance to check for obstacles", "Checking the aircraft all around, e.g. panels and doors closed", "Walking around the tractor to inspect the vehicle's condition", "Reading the route back step by step with the controller"], "ans": 1, "expJa": "準備作業の一つとして、全てのパネルやドアが閉じているかなど航空機の周囲360度を確認することをサークル・チェックと呼んでいる。", "expVi": "Một trong các công tác chuẩn bị là kiểm tra toàn bộ 360 độ quanh tàu bay, ví dụ mọi panel và cửa đã đóng chưa; việc này gọi là サークル・チェック.", "expEn": "One preparation step is checking the whole 360 degrees around the aircraft, such as all panels and doors being closed; this is called the circle check."},
  {"id": "S2R18", "topic": "s2_ramp", "level": 2, "src": "SSW2テキスト 2-3-3 (p.18)", "qJa": "トーイングの資格取得において、座学・実技の訓練の後に受ける熟練訓練（実機による慣熟訓練）の期間はおよそどれくらいか？", "qVi": "Khi lấy chứng chỉ kéo tàu bay, sau đào tạo lý thuyết và thực hành, thời gian huấn luyện thuần thục (trên máy bay thật) là khoảng bao lâu?", "qEn": "For the towing qualification, about how long is the proficiency training on real aircraft after classroom and practical training?", "optsJa": ["1カ月ほど", "6カ月ほど", "1年ほど", "3カ月ほど"], "optsVi": ["Khoảng 1 tháng", "Khoảng 6 tháng", "Khoảng 1 năm", "Khoảng 3 tháng"], "optsEn": ["About 1 month", "About 6 months", "About 1 year", "About 3 months"], "ans": 3, "expJa": "トーイングの資格は、座学と実技の訓練の後、実機で実施要領に慣れる3カ月ほどの熟練訓練を経て、技能評価に合格する必要がある。", "expVi": "Chứng chỉ kéo đòi hỏi sau khi học lý thuyết và thực hành, phải trải qua khoảng 3 tháng huấn luyện làm quen trên máy bay thật rồi đậu đánh giá kỹ năng.", "expEn": "After classroom and practical training, trainees spend about 3 months becoming proficient on real aircraft, then must pass a skills evaluation."},
  {"id": "S2R19", "topic": "s2_ramp", "level": 2, "src": "SSW2テキスト 2-3-4 (p.18-19)", "qJa": "プッシュ・バックについて、テキストの記述として正しいものはどれか？", "qVi": "Về đẩy lùi tàu bay (プッシュ・バック), nội dung nào đúng theo giáo trình?", "qEn": "Regarding pushback, which statement matches the textbook?", "optsJa": ["プッシュ・バック中にエンジンを始動することは一切ない", "トーイングとは別に独立した専用の資格が必要である", "大型機はトーイング時より100トン以上重いことがある", "到着機をスポットへ押し込んで駐機させる作業である"], "optsVi": ["Không bao giờ khởi động động cơ trong khi đẩy lùi", "Cần một chứng chỉ độc lập, tách khỏi chứng chỉ kéo", "Máy bay lớn có thể nặng hơn lúc kéo trên 100 tấn", "Là công việc đẩy máy bay vừa đến vào trong vị trí đỗ"], "optsEn": ["Engines are never started while a pushback is underway", "A separate qualification independent of towing is required", "A large aircraft may be over 100 tons heavier than when towed", "It is the job of pushing arriving aircraft into the spot"], "ans": 2, "expJa": "出発機は旅客・燃料・手荷物・貨物を積んでいるため、大型機ではトーイング時より100トン以上重くなることがある。押し出し中にエンジンを始動する場合もあり、トーイング資格の一部として扱われる。", "expVi": "Máy bay khởi hành chở khách, nhiên liệu, hành lý, hàng hóa nên máy bay lớn có thể nặng hơn lúc kéo 100 tấn trở lên. Động cơ có thể được khởi động trong lúc đẩy lùi, và việc này thuộc chứng chỉ kéo.", "expEn": "A departing aircraft carries passengers, fuel, baggage and cargo, so a large one can be over 100 tons heavier than when towed. Engines may be started during pushback, and it is part of the towing qualification."},
  {"id": "S2R20", "topic": "s2_ramp", "level": 2, "src": "SSW2テキスト 2-4-3 (p.20-21)", "qJa": "ブレーキマンの作業上の注意として、誤っているものはどれか？", "qVi": "Trong các lưu ý khi làm người phanh (ブレーキマン), nội dung nào KHÔNG đúng?", "qEn": "Which is NOT correct as a precaution for brakeman work?", "optsJa": ["必要に応じて操縦桿で機体の向きを補正する", "ブレーキマンの定位置は機長席とする", "コクピットへは原則エントランス・ドアを使う", "緊急時以外はトーイング中にブレーキを操作しない"], "optsVi": ["Khi cần, dùng cần lái để chỉnh hướng tàu bay", "Vị trí cố định của người phanh là ghế cơ trưởng", "Vào buồng lái về nguyên tắc qua cửa ra vào hành khách", "Ngoài trường hợp khẩn cấp không thao tác phanh khi kéo"], "optsEn": ["Use the control column to adjust heading if needed", "The brakeman's set position is the captain's seat", "Enter the cockpit through the entrance door in principle", "Never operate the brakes during towing except in emergency"], "ans": 0, "expJa": "テキストでは、操縦桿に触れることは絶対に禁止とされている。定位置は機長席、通路は原則エントランス・ドア、トーイング中のブレーキは緊急時のみ操作する。", "expVi": "Giáo trình quy định tuyệt đối không được chạm vào cần lái. Vị trí là ghế cơ trưởng, lối vào về nguyên tắc là cửa ra vào, và chỉ thao tác phanh khi khẩn cấp.", "expEn": "The textbook says never to touch the control column. The set position is the captain's seat, entry is normally via the entrance door, and brakes are used only in an emergency."},
  {"id": "S2R21", "topic": "s2_ramp", "level": 2, "src": "SSW2テキスト 2-5-2 (p.22)", "qJa": "ウォッチマンが2人以上で作業しているとき、1人が安全確保のためストップの合図を出した場合、他のウォッチマンはどうするか？", "qVi": "Khi có từ 2 người canh (ウォッチマン) trở lên, nếu một người ra hiệu dừng để đảm bảo an toàn thì những người còn lại làm gì?", "qEn": "When two or more watchmen are working and one gives a stop signal for safety, what should the others do?", "optsJa": ["他のウォッチマンも同一の合図をする", "自分の担当が安全なら通過よしを続ける", "マーシャラーの判断が出るまで合図を止める", "合図を出した者が管制官へ報告するのを待つ"], "optsVi": ["Những người canh khác cũng ra cùng tín hiệu", "Nếu phần mình phụ trách an toàn thì tiếp tục báo qua được", "Ngừng ra hiệu cho đến khi marshaller quyết định", "Chờ người ra hiệu báo cáo lên kiểm soát viên"], "optsEn": ["The other watchmen give the same signal", "Keep signaling all clear if their own area is safe", "Stop signaling until the marshaller decides", "Wait for that watchman to report to the controller"], "ans": 0, "expJa": "複数のウォッチマンはできるだけ相互に連絡をとり、誰か1人がストップや徐行の合図を出したら、残りのウォッチマンも同じ合図を出すことになっている。", "expVi": "Nhiều người canh phải liên lạc với nhau càng nhiều càng tốt; chỉ cần một người ra hiệu dừng hay đi chậm thì những người khác cũng ra hiệu giống vậy.", "expEn": "Multiple watchmen keep in contact as much as possible, and if even one gives a stop or slow signal, the others give the same signal."},
  {"id": "S2R22", "topic": "s2_ramp", "level": 2, "src": "SSW2テキスト 2-5-3 (p.22-23)", "qJa": "到着時や出発時のウォッチマン作業で、エンジン始動時に立ち入ってはならない範囲として示されているものはどれか？", "qVi": "Khi làm người canh lúc đến hoặc khởi hành, phạm vi nào được nêu là không được đi vào khi động cơ khởi động?", "qEn": "During watchman work at arrival or departure, which area must not be entered when engines are started?", "optsJa": ["エンジン外側15mより内側", "エンジン外側5mより内側", "エンジン外側1.5mより内側", "エンジン外側40mより内側"], "optsVi": ["Phía trong 15m tính từ bên ngoài động cơ", "Phía trong 5m tính từ bên ngoài động cơ", "Phía trong 1,5m tính từ bên ngoài động cơ", "Phía trong 40m tính từ bên ngoài động cơ"], "optsEn": ["Within 15 m of the engine's outer side", "Within 5 m of the engine's outer side", "Within 1.5 m of the engine's outer side", "Within 40 m of the engine's outer side"], "ans": 1, "expJa": "到着時・出発時とも、エンジン始動時は危険区域に入ってはならず、エンジン外側から5mより内側に立ち入らないよう注記されている。", "expVi": "Cả lúc đến và lúc khởi hành, khi động cơ khởi động không được vào khu nguy hiểm, và có ghi chú không đi vào trong phạm vi 5m tính từ phía ngoài động cơ.", "expEn": "For both arrival and departure, the notes say not to enter the hazard area at engine start and not to go within 5 m of the engine's outer side."},
  {"id": "S2L01", "topic": "s2_load", "level": 2, "src": "SSW2テキスト 3-1-1 (p.24)", "qJa": "ロード・プランの説明として正しいものはどれか？", "qVi": "Mô tả nào đúng về kế hoạch chất xếp (ロード・プラン)?", "qEn": "Which statement correctly describes a load plan?", "optsJa": ["離陸から着陸までの飛行時間や飛行ルートを定めた運航上の計画", "予約数・座席位置・重心を考慮し貨物室への搭載を決める計画", "出発便で使用するGSEの台数と配置場所を事前に決める計画", "搭乗旅客の座席を体重に応じて割り当て直すための計画"], "optsVi": ["Kế hoạch xác định thời gian bay và đường bay từ lúc cất cánh đến khi hạ cánh", "Kế hoạch xếp hàng vào khoang hàng dựa trên số đặt chỗ, vị trí ghế và trọng tâm", "Kế hoạch quyết định trước số lượng và vị trí bố trí GSE dùng cho chuyến bay đi", "Kế hoạch sắp xếp lại ghế ngồi của hành khách theo cân nặng của từng người"], "optsEn": ["A plan fixing the flight time and route from takeoff to landing", "A plan for loading the holds based on bookings, seat positions and CG", "A plan deciding in advance how many GSE units to use and where to park them", "A plan for reassigning passenger seats according to each person's body weight"], "ans": 1, "expJa": "テキストでは、旅客の予約数や座席位置を確かめ、重心位置を考えながら貨物・郵便物・手荷物を貨物室にどう積むかを計画することをロード・プランとしている。飛行時間やルートの計画はフライト・プランである。", "expVi": "Theo giáo trình, ロード・プラン là việc lập kế hoạch xếp hàng hóa, bưu phẩm, hành lý vào khoang hàng, có xét số đặt chỗ, vị trí ghế của khách và vị trí trọng tâm. Kế hoạch thời gian và đường bay là フライト・プラン.", "expEn": "The textbook defines a load plan as planning how cargo, mail and baggage go into the holds while checking bookings and seat positions and considering the aircraft's centre of gravity. Flight time and route belong to the flight plan."},
  {"id": "S2L02", "topic": "s2_load", "level": 2, "src": "SSW2テキスト 3-1-2 (p.24-25)", "qJa": "ACL（Allowable Cabin Load）の意味として正しいものはどれか？", "qVi": "ACL (Allowable Cabin Load) có nghĩa là gì?", "qEn": "What does ACL (Allowable Cabin Load) mean?", "optsJa": ["機体の自重に搭載燃料の重量を加えた重量", "航空機が安全に着陸できる最大の重量", "旅客・貨物・郵便物・手荷物を搭載できる重量", "貨物室の床が1区画あたりに耐えられる最大の重量"], "optsVi": ["Trọng lượng rỗng của máy bay cộng với trọng lượng nhiên liệu", "Trọng lượng tối đa mà máy bay có thể hạ cánh an toàn", "Trọng lượng có thể chở gồm khách, hàng hóa, bưu phẩm, hành lý", "Trọng lượng tối đa mà sàn mỗi ngăn khoang hàng có thể chịu được"], "optsEn": ["The aircraft's empty weight plus the weight of fuel on board", "The maximum weight at which the aircraft can land safely", "The weight available for passengers, cargo, mail and baggage", "The maximum weight each section of the hold floor can withstand"], "ans": 2, "expJa": "ACLは旅客・貨物・郵便物・手荷物を積むことのできる重量で、フライト・プラン作成後の乗員との打合わせで決まる。ロード・プラン担当者はこれを超えないよう計画する。", "expVi": "ACL là trọng lượng có thể chở khách, hàng hóa, bưu phẩm và hành lý; được quyết định trong buổi trao đổi với tổ bay sau khi lập フライト・プラン. Người lập ロード・プラン phải lên kế hoạch không vượt quá ACL.", "expEn": "ACL is the weight that can be used for passengers, cargo, mail and baggage. It is fixed in the briefing with the crew after the flight plan is made, and the load planner must not exceed it."},
  {"id": "S2L03", "topic": "s2_load", "level": 2, "src": "SSW2テキスト 3-1-2 (p.24)", "qJa": "作成されたロード・プランについて、航空法で義務付けられていることはどれか？", "qVi": "Đối với ロード・プラン đã lập, Luật Hàng không (航空法) bắt buộc điều gì?", "qEn": "Under the Civil Aeronautics Act, what is required for a completed load plan?", "optsJa": ["航空交通管制機関に提出して承認を得ること", "機長が搭乗前に署名して機内に保管すること", "国土交通大臣へ毎月まとめて報告すること", "運航整備士の点検を受けて押印をもらうこと"], "optsVi": ["Nộp cho cơ quan kiểm soát không lưu và được phê duyệt", "Cơ trưởng ký trước khi lên máy bay và cất giữ trên tàu", "Báo cáo tổng hợp hằng tháng lên Bộ trưởng Bộ Đất đai", "Được thợ máy kiểm tra và đóng dấu xác nhận"], "optsEn": ["Submit it to the air traffic control authority for approval", "Have the captain sign it before boarding and keep it on board", "Report it monthly in a batch to the transport minister", "Have a line mechanic inspect it and stamp it"], "ans": 0, "expJa": "テキストによれば、ロード・プランは航空交通管制機関へ提出し承認を受けることが航空法で義務となっている。", "expVi": "Theo giáo trình, 航空法 bắt buộc phải nộp ロード・プラン cho cơ quan kiểm soát không lưu (航空交通管制機関) và được phê duyệt.", "expEn": "According to the textbook, the Civil Aeronautics Act requires the load plan to be submitted to the air traffic control authority and approved."},
  {"id": "S2L04", "topic": "s2_load", "level": 2, "src": "SSW2テキスト 3-2-1 (p.26)", "qJa": "航空機の全備重量は、大きく何と何に分けられるか？", "qVi": "Tổng trọng lượng (全備重量) của máy bay được chia chủ yếu thành hai phần nào?", "qEn": "Into which two main parts is the aircraft's gross weight divided?", "optsJa": ["自重と燃料重量", "有償重量と旅客重量", "着陸重量と燃料重量", "自重と積載重量"], "optsVi": ["Trọng lượng rỗng và nhiên liệu", "Tải trọng thương mại và khách", "Trọng lượng hạ cánh và trọng lượng nhiên liệu", "Trọng lượng rỗng và tải trọng chất"], "optsEn": ["Empty weight and fuel weight", "Payload and passenger weight", "Landing weight and fuel load weight", "Empty weight and loaded weight"], "ans": 3, "expJa": "テキストでは、全備重量は自重と積載重量に大別できると説明され、図3-2で示されている。", "expVi": "Giáo trình giải thích 全備重量 được chia lớn thành trọng lượng rỗng (自重) và trọng lượng chất tải (積載重量), minh họa ở hình 3-2.", "expEn": "The textbook explains that gross weight is broadly split into empty weight and loaded weight, as shown in Figure 3-2."},
  {"id": "S2L05", "topic": "s2_load", "level": 2, "src": "SSW2テキスト 3-2-1 (p.26)", "qJa": "ペイロードについての説明として正しいものはどれか？", "qVi": "Mô tả nào đúng về tải trọng thương mại (ペイロード)?", "qEn": "Which statement about payload is correct?", "optsJa": ["機体の自重のことで、同じ機種であれば常に一定である", "有償重量のことで、航空会社の収入となるものである", "搭載燃料の重量のことで、天候によって増減する", "乗員と機内用品の重量で、便ごとに変わらない"], "optsVi": ["Là trọng lượng rỗng, luôn cố định nếu cùng loại máy bay", "Là trọng lượng có thu phí, trở thành doanh thu hãng bay", "Là trọng lượng nhiên liệu chở theo, tăng giảm theo thời tiết", "Là trọng lượng tổ bay và đồ dùng, không đổi theo chuyến"], "optsEn": ["The empty weight, always fixed for the same type", "The revenue weight, which earns the airline income", "The fuel weight on board, which varies with the weather", "Crew and supplies weight, the same on every flight"], "ans": 1, "expJa": "有償重量はペイロードとも呼ばれ、航空会社の収入となる。ペイロードが重いほど利益は増すが、全備重量を超える場合は貨物・郵便物を減らす必要がある。", "expVi": "有償重量 còn gọi là ペイロード, là nguồn thu của hãng bay. Payload càng nặng lợi nhuận càng tăng, nhưng nếu vượt 全備重量 thì phải giảm hàng hóa, bưu phẩm.", "expEn": "Revenue weight, also called payload, is what earns the airline income. More payload means more profit, but if gross weight would be exceeded, cargo and mail must be reduced."},
  {"id": "S2L06", "topic": "s2_load", "level": 2, "src": "SSW2テキスト 3-2-1 (p.26)", "qJa": "悪天候や強い向かい風の中で運航し、燃料を余分に積む場合について、テキストの記述に合うものはどれか？", "qVi": "Khi bay trong thời tiết xấu hoặc gió ngược mạnh và phải nạp thêm nhiên liệu, điều nào phù hợp với giáo trình?", "qEn": "When extra fuel must be loaded for bad weather or strong headwinds, which statement matches the textbook?", "optsJa": ["貨物・郵便物のほか旅客も減らす場合がある", "最大離陸重量を一時的に超えることが許される", "手荷物はすべて後続便に回さなければならない", "ACLが増えるため貨物を追加で搭載できる"], "optsVi": ["Có khi phải giảm cả hành khách ngoài hàng hóa, bưu phẩm", "Được phép tạm thời bay vượt trọng lượng cất cánh tối đa", "Toàn bộ hành lý bắt buộc phải chuyển hết sang chuyến sau", "Vì ACL tăng lên nên có thể chất thêm hàng hóa"], "optsEn": ["Passengers may have to be cut as well as cargo and mail", "Exceeding maximum takeoff weight is temporarily allowed", "All checked baggage must be moved to a later flight", "ACL becomes larger, so more cargo can be loaded on board"], "ans": 0, "expJa": "余分な燃料を積む必要があるときは、貨物・郵便物に加えて乗客まで減らさなければならないことがあるとテキストに書かれている。全備重量（最大離陸重量）を超えての飛行は認められない。", "expVi": "Giáo trình ghi khi phải chở thêm nhiên liệu, có trường hợp phải giảm cả hành khách ngoài hàng hóa và bưu phẩm. Máy bay không được bay vượt 全備重量 (trọng lượng cất cánh tối đa).", "expEn": "The textbook says that when extra fuel is needed, passengers may have to be reduced in addition to cargo and mail. Flying above gross (maximum takeoff) weight is not allowed."},
  {"id": "S2L07", "topic": "s2_load", "level": 2, "src": "SSW2テキスト 3-3-1 (p.26)", "qJa": "機体のコンテナ室へULD単位で積み降ろしを行う際に使用されるGSEはどれか？", "qVi": "Khi xếp/dỡ theo đơn vị ULD vào khoang container của máy bay, dùng GSE nào?", "qEn": "Which GSE is used to load and unload ULDs into the aircraft's container hold?", "optsJa": ["ベルト・ローダー", "ハイリフト・ローダー", "トーイング・トラクター", "コンテナ・ドーリー"], "optsVi": ["Xe băng chuyền (ベルト・ローダー)", "Xe nâng hàng (ハイリフト・ローダー)", "Xe kéo (トーイング・トラクター)", "Xe đẩy container (コンテナ・ドーリー)"], "optsEn": ["Belt loader", "High-lift loader", "Towing tractor", "Container dolly"], "ans": 1, "expJa": "コンテナ室へのULD単位の搭降載にはハイリフト・ローダーが使われる。ベルト・ローダーはバルク室で手作業の積み降ろしに用いる。", "expVi": "Xếp/dỡ ULD vào khoang container dùng ハイリフト・ローダー. ベルト・ローダー dùng cho khoang hàng rời (バルク), xếp dỡ bằng tay.", "expEn": "High-lift loaders are used for ULD loading into the container hold. Belt loaders serve the bulk hold, where items are handled by hand."},
  {"id": "S2L08", "topic": "s2_load", "level": 2, "src": "SSW2テキスト 3-3-6 (p.30)", "qJa": "国際線貨物のうち「仮陸揚げ貨物」の説明として正しいものはどれか？", "qVi": "Trong hàng quốc tế, mô tả nào đúng về \"hàng dỡ tạm\" (仮陸揚げ貨物)?", "qEn": "Among international cargo, which correctly describes \"temporarily landed cargo\"?", "optsJa": ["国内で生産され、税関から輸出許可を受けた貨物", "外国から到着し、まだ輸入許可を受けていない貨物", "国内の他の保税地域で輸入許可を受けようとする貨物", "外航機に再び積み替えるため、仮に陸揚げした貨物"], "optsVi": ["Hàng sản xuất trong nước, đã được hải quan cho phép xuất khẩu", "Hàng đến từ nước ngoài, chưa được hải quan cho phép nhập khẩu", "Hàng định xin phép nhập khẩu tại khu ngoại quan khác trong nước", "Hàng được đưa lên bờ tạm để chuyển lại lên máy bay nước ngoài"], "optsEn": ["Goods made in Japan that customs has cleared for export", "Goods arrived from abroad not yet cleared for import", "Goods to be cleared for import at another bonded area in Japan", "Goods landed temporarily for reloading onto a foreign carrier"], "ans": 3, "expJa": "仮陸揚げ貨物は、外航機に積み替えるため一時的に陸揚げしたものである。他の選択肢はそれぞれ輸出通関済み貨物、輸入未通関貨物、保税運送の説明である。", "expVi": "仮陸揚げ貨物 là hàng được đưa lên bờ tạm thời để chuyển lại lên máy bay của hãng nước ngoài. Các lựa chọn khác lần lượt là hàng đã thông quan xuất khẩu, hàng chưa thông quan nhập khẩu và vận chuyển ngoại quan (保税運送).", "expEn": "Temporarily landed cargo is cargo landed for a short time so it can be transferred onto a foreign carrier. The other options describe export-cleared cargo, uncleared import cargo and bonded transport."},
  {"id": "S2L09", "topic": "s2_load", "level": 2, "src": "SSW2テキスト 4-1-1 (p.32)", "qJa": "危険物を搭載した場合に行うこととして、テキストに記載されているものはどれか？", "qVi": "Khi đã chất hàng nguy hiểm, việc nào được ghi trong giáo trình?", "qEn": "When dangerous goods have been loaded, what does the textbook say must be done?", "optsJa": ["NOTOCに署名し、出発機の機長に伝える", "ロード・シートを税関へ提出して許可を受ける", "客室乗務員へ口頭で伝え、書類には残さない", "危険物の個数を運航管理者へFAXで報告する"], "optsVi": ["Ký vào NOTOC và thông báo cho cơ trưởng chuyến bay đi", "Nộp phiếu chất tải (ロード・シート) cho hải quan xin phép", "Báo miệng cho tiếp viên, không cần ghi vào giấy tờ", "Báo số kiện hàng nguy hiểm cho điều phái viên bằng FAX"], "optsEn": ["Sign the NOTOC and inform the departing captain", "Submit the load sheet to customs and obtain permission", "Tell the cabin crew verbally without any paperwork", "Fax the number of dangerous goods pieces to dispatch"], "ans": 0, "expJa": "危険物は規定どおり正確に積まれたことを確認し、所定書類NOTOC（NOtification TO Captain）に署名して出発機の機長に伝えることになっている。", "expVi": "Với hàng nguy hiểm, phải xác nhận đã chất đúng quy định, ký vào giấy tờ NOTOC (NOtification TO Captain) và thông báo cho cơ trưởng chuyến bay đi.", "expEn": "For dangerous goods, correct loading per the rules is confirmed, then the NOTOC (NOtification TO Captain) is signed and the departing captain is informed."},
  {"id": "S2L10", "topic": "s2_load", "level": 2, "src": "SSW2テキスト 4-1-1 (p.33)", "qJa": "チェック・イン・カウンター締め切り後に搭乗手続きをした旅客の手荷物は、通常どのように搭載されるか？", "qVi": "Hành lý của khách làm thủ tục sau khi quầy check-in đã đóng thường được chất lên máy bay như thế nào?", "qEn": "How is baggage from a passenger who checked in after counter closing normally loaded?", "optsJa": ["ソーティング・エリアで改めて仕分けてから搭載する", "次の便に回すため手荷物仕分け場で一時保管する", "ゲート旅客担当者が搭載担当者へ直接渡して搭載する", "旅客自身が機側まで運び、搭載担当者に手渡す"], "optsVi": ["Phân loại lại tại khu phân loại (ソーティング・エリア) rồi mới chất", "Giữ tạm tại khu phân loại hành lý để chuyển sang chuyến sau", "Nhân viên cửa ra máy bay giao thẳng cho nhân viên chất xếp", "Hành khách tự mang ra cạnh máy bay giao cho nhân viên chất xếp"], "optsEn": ["It is re-sorted in the sorting area before loading", "It is held in the sorting area for a later flight", "Gate staff hand it directly to the loading staff", "The passenger carries it planeside to the loaders"], "ans": 2, "expJa": "締め切り後に受託した手荷物はソーティング・エリアを通さず、ゲートの旅客担当者が搭載担当者へ直接引き渡して積む。空港によってはダムウェーターを使うこともある。", "expVi": "Hành lý nhận sau giờ đóng quầy không qua ソーティング・エリア; nhân viên phục vụ khách tại cửa ra máy bay giao trực tiếp cho nhân viên chất xếp. Một số sân bay dùng thang ダムウェーター.", "expEn": "Baggage accepted after closing skips the sorting area; gate passenger staff hand it straight to the loading staff. Some airports use a dumbwaiter lift instead."},
  {"id": "S2L11", "topic": "s2_load", "level": 2, "src": "SSW2テキスト 4-1-3 (p.33)", "qJa": "作業態度に関する記述として、誤っているものはどれか？", "qVi": "Về thái độ làm việc, câu nào KHÔNG đúng?", "qEn": "Which statement about work attitude is NOT correct?", "optsJa": ["服装・態度は厳正でなければならない", "車両等の誘導・合図・連絡は明確に行う", "ランプでは周囲の機体と車両の動きに常に注意する", "作業後の確認は時間短縮のため他人に任せる"], "optsVi": ["Trang phục và thái độ luôn phải nghiêm chỉnh, đúng mực", "Dẫn đường, ra hiệu, liên lạc xe cộ phải rõ ràng", "Trên sân đỗ luôn chú ý máy bay và xe xung quanh", "Kiểm tra sau khi làm thì giao người khác cho nhanh"], "optsEn": ["Dress and conduct must be strict and proper", "Guiding, signals and contact for vehicles must be clear", "On the ramp, always watch nearby aircraft and vehicles", "Leave post-work checks to others to save time"], "ans": 3, "expJa": "テキストでは、作業終了後は自分が行った作業を自分自身で客観的に確認しなければならないとしている。すべての作業は確認の積み重ねだとされる。", "expVi": "Giáo trình yêu cầu sau khi xong việc, chính mình phải tự kiểm tra khách quan công việc đã làm; mọi công việc đều là sự tích lũy của các lần xác nhận.", "expEn": "The textbook says workers must objectively check their own work themselves after finishing; all work is a build-up of checks."},
  {"id": "S2L12", "topic": "s2_load", "level": 2, "src": "SSW2テキスト 4-1-6 (p.35)", "qJa": "貨物室で塩水の漏洩を発見した場合の対応として正しいものはどれか？", "qVi": "Khi phát hiện nước muối rò rỉ trong khoang hàng, cách xử lý nào đúng?", "qEn": "If a salt-water leak is found in the hold, what is the correct action?", "optsJa": ["記録だけ残し、到着地の係員に処理を任せる", "直ちに整備士へ連絡し、処置を依頼する", "搭載担当者が水で洗い流してから報告する", "漏れた貨物をバルク室へ移し搭載を続ける"], "optsVi": ["Chỉ ghi lại rồi để nhân viên ở điểm đến xử lý", "Liên lạc ngay với thợ máy và nhờ xử lý", "Nhân viên chất xếp rửa sạch bằng nước rồi báo", "Chuyển hàng rò rỉ sang khoang rời và tiếp tục"], "optsEn": ["Just record it and let destination staff handle it", "Contact a mechanic at once and ask for action", "Loaders rinse it with water and report later", "Move the leaking item to bulk and keep loading"], "ans": 1, "expJa": "塩水が漏れると機体構造部に腐食などが生じるため、漏洩を見つけたらすぐに整備士に連絡して処置を頼むとテキストにある。", "expVi": "Nước muối rò rỉ có thể gây ăn mòn kết cấu máy bay, nên khi phát hiện phải liên lạc ngay với thợ máy (整備士) để nhờ xử lý.", "expEn": "Leaked salt water can corrode the airframe structure, so the textbook says to contact a mechanic immediately and ask them to deal with it."},
  {"id": "S2L13", "topic": "s2_load", "level": 2, "src": "SSW2テキスト 4-3 (p.37)", "qJa": "「機移し（SHIP TO SHIP）」の説明として正しいものはどれか？", "qVi": "Mô tả nào đúng về \"chuyển thẳng giữa máy bay\" (機移し / SHIP TO SHIP)?", "qEn": "Which correctly describes \"ship to ship\" transfer (機移し)?", "optsJa": ["貨物を一旦上屋へ入れ、検査後に別の出発便へ積み替えること", "到着した搭載物を上屋や仕分け場へ入れず出発便へ直接運ぶこと", "機材変更の際に、全ULDを同じ配置のまま新しい機体へ移すこと", "前方貨物室の搭載物を後方へ移して重心位置を調整すること"], "optsVi": ["Đưa hàng vào kho trước, kiểm tra rồi chuyển sang chuyến đi khác", "Chở thẳng hàng vừa đến sang máy bay chuyến đi, không qua kho", "Khi đổi tàu bay, chuyển toàn bộ ULD sang máy bay mới theo bố trí cũ", "Chuyển hàng từ khoang trước ra khoang sau để điều chỉnh trọng tâm"], "optsEn": ["Storing cargo in the terminal, then reloading it on another flight after checks", "Carrying arriving items straight to a departing aircraft, bypassing terminals", "Moving all ULDs to a replacement aircraft in the same layout on a swap", "Shifting items from the forward hold to the aft hold to adjust the CG"], "ans": 1, "expJa": "機移しとは、出発時刻が迫っているなどの理由で、到着した貨物・郵便物・手荷物を上屋やソーティング・エリアに搬入せず、出発便の機体へ直接搬送することをいう。", "expVi": "機移し là khi giờ khởi hành sắp đến, hàng hóa, bưu phẩm, hành lý vừa đến được chở thẳng sang máy bay chuyến đi mà không đưa vào kho hay ソーティング・エリア.", "expEn": "Ship to ship means taking arriving cargo, mail or baggage directly to the departing aircraft, without going through the terminals or sorting area, for reasons such as a near departure time."},
  {"id": "S2L14", "topic": "s2_load", "level": 2, "src": "SSW2テキスト 4-3 (p.37)", "qJa": "搭載管理システムが導入されていない、または使えない場合、出発手荷物のULD確認に使用する書類はどれか？", "qVi": "Khi không có hoặc không dùng được hệ thống quản lý chất xếp, giấy tờ nào dùng để xác nhận ULD hành lý chuyến đi?", "qEn": "If the loading control system is not available, which document is used to check departing baggage ULDs?", "optsJa": ["貨物部門で準備されたデリバリー・シート", "搬送担当者が持参するマニフェスト", "搭載監督者が署名するS/Lシート", "ロード・コントロール作成のLIR"], "optsVi": ["Phiếu giao hàng (デリバリー・シート) do bộ phận hàng hóa chuẩn bị", "Bản kê hàng (マニフェスト) do nhân viên vận chuyển mang theo", "Phiếu S/L (Special Load) do giám sát chất xếp ký", "Báo cáo LIR do bộ phận ロード・コントロール lập"], "optsEn": ["Delivery sheet prepared by the cargo section", "Manifest carried by the transport staff", "S/L sheet signed by the load master", "LIR prepared by load control"], "ans": 3, "expJa": "システムが使えない場合は、ロード・コントロール担当者が作ったLIR（Loading Instruction Report）を使う。デリバリー・シートは出発貨物の場合に用いる書類である。", "expVi": "Khi không dùng được hệ thống, dùng LIR do người phụ trách ロード・コントロール lập. デリバリー・シート là giấy tờ dùng cho hàng hóa chuyến đi.", "expEn": "When the system cannot be used, the LIR prepared by load control is used. The delivery sheet is the document for departing cargo instead."},
  {"id": "S2L15", "topic": "s2_load", "level": 2, "src": "SSW2テキスト 4-3 (p.37)", "qJa": "郵便物を搭載する「郵便指定便」は、いつ決定されるか？", "qVi": "\"Chuyến bay chỉ định bưu phẩm\" (郵便指定便) được quyết định khi nào?", "qEn": "When are the \"designated mail flights\" decided?", "optsJa": ["前の週", "出発当日", "前の月", "前の年度"], "optsVi": ["Tuần trước đó", "Ngày khởi hành", "Tháng trước đó", "Năm trước đó"], "optsEn": ["The previous week", "The departure day", "The previous month", "The previous year"], "ans": 2, "expJa": "郵便物は前月に決まる「郵便指定便」に積まれる。臨時に他の便へ積む場合は、貨物管理システムに情報が反映される。", "expVi": "Bưu phẩm được chất lên 郵便指定便 quyết định từ tháng trước. Nếu phát sinh chất tạm thời lên chuyến khác, thông tin được cập nhật vào hệ thống quản lý hàng hóa.", "expEn": "Mail goes on the designated mail flights decided the month before. Any extra loading on other flights is reflected in the cargo management system."},
  {"id": "S2L16", "topic": "s2_load", "level": 2, "src": "SSW2テキスト 4-4-2 (p.39)", "qJa": "機側でのトーイング・トラクター（TT車）の走行速度はどう定められているか？", "qVi": "Tốc độ xe kéo (トーイング・トラクター / TT車) khi chạy cạnh máy bay được quy định thế nào?", "qEn": "What speed is set for towing tractors (TT) near the aircraft?", "optsJa": ["3km/h以下", "5km/h以下", "10km/h以下", "15km/h以下"], "optsVi": ["Dưới 3km/h", "Dưới 5km/h", "Dưới 10km/h", "Dưới 15km/h"], "optsEn": ["3 km/h or less", "5 km/h or less", "10 km/h or less", "15 km/h or less"], "ans": 1, "expJa": "テキストでは、機側でのTT車は5km/h以下で走行するとされている。", "expVi": "Giáo trình quy định xe TT chạy cạnh máy bay với tốc độ 5km/h trở xuống.", "expEn": "The textbook states that TT vehicles near the aircraft travel at 5 km/h or below."},
  {"id": "S2L17", "topic": "s2_load", "level": 2, "src": "SSW2テキスト 4-4-4 (p.42)", "qJa": "コンテナ搭載前に、ブリッジのガイドレールを貨物室側面のガイドと並列に調整しなければならない理由はどれか？", "qVi": "Vì sao trước khi chất container phải chỉnh ray dẫn của cầu (ブリッジ) song song với thanh dẫn bên hông khoang hàng?", "qEn": "Why must the bridge guide rail be aligned with the hold's lateral guide before loading a container?", "optsJa": ["ハイリフト・ローダーの移送速度を上げられるようにするため", "コンテナの重量を搭載前に正確に計測するため", "ULDがドア・シルに接触し機体を損傷しないため", "ドライブ・タイヤの摩耗を左右で均等にするため"], "optsVi": ["Để tăng tốc độ vận chuyển ULD của xe nâng hàng", "Để đo chính xác trọng lượng container trước khi chất", "Để ULD không va vào ngưỡng cửa làm hỏng máy bay", "Để lốp dẫn động mòn đều ở cả hai bên"], "optsEn": ["To let the high-lift loader move ULDs faster", "To weigh the container accurately before loading", "To keep the ULD off the door sill and avoid damage", "To make the drive tyres wear evenly on both sides"], "ans": 2, "expJa": "調整をしないとULDがシップ・ドア・シルに接触し機体損傷の原因になるため、搭載前に必ず行う。微調整はガイドレール調整ハンドルで行う。", "expVi": "Nếu không chỉnh, ULD sẽ chạm vào ngưỡng cửa (シップ・ドア・シル) gây hư hỏng thân máy bay, nên luôn phải chỉnh trước khi chất. Tinh chỉnh bằng tay quay điều chỉnh ray dẫn.", "expEn": "Without this adjustment the ULD can strike the door sill and damage the aircraft, so it is always done before loading, using the guide rail adjustment handle."},
  {"id": "S2L18", "topic": "s2_load", "level": 2, "src": "SSW2テキスト 4-4-4 (p.44)", "qJa": "パーシャル・ロード（部分搭載）があった場合、貨物室ドアを閉める前に必要なことはどれか？", "qVi": "Nếu có chất một phần (パーシャル・ロード), trước khi đóng cửa khoang hàng cần làm gì?", "qEn": "If there is a partial load, what is required before closing the cargo door?", "optsJa": ["機長から承認をもらう", "ロード・コントロールへ電話する", "整備士がドアを点検する", "搭載監督者の現場確認を受ける"], "optsVi": ["Xin phê duyệt trước của cơ trưởng chuyến bay", "Gọi điện báo cho bộ phận ロード・コントロール", "Nhờ thợ máy kiểm tra cửa khoang hàng", "Được giám sát chất xếp kiểm tra tại chỗ"], "optsEn": ["Obtain the captain's approval first", "Phone the load control section", "Have a mechanic inspect the door", "Get the load master's on-site check"], "ans": 3, "expJa": "部分搭載があった場合は、ドアを閉める前に搭載監督者（Load Master）の現場確認を受けることとされている。", "expVi": "Khi có chất một phần, trước khi đóng cửa phải được giám sát chất xếp (Load Master / 搭載監督者) đến kiểm tra tại chỗ.", "expEn": "With a partial load, the load master must check it on site before the door is closed."},
  {"id": "S2L19", "topic": "s2_load", "level": 2, "src": "SSW2テキスト 4-5-1 (p.45)", "qJa": "バルク貨物をベルト・ローダーのコンベアに乗せるとき、室内の搭載担当者が取りやすいようにあける間隔はどのくらいか？", "qVi": "Khi đặt hàng rời lên băng chuyền của ベルト・ローダー, nên để khoảng cách bao nhiêu để người bên trong khoang dễ lấy?", "qEn": "When placing bulk cargo on the belt loader, what spacing is left so the loader inside can take it easily?", "optsJa": ["10cmくらい", "30cmくらい", "50cmくらい", "100cmくらい"], "optsVi": ["Khoảng 10cm", "Khoảng 30cm", "Khoảng 50cm", "Khoảng 100cm"], "optsEn": ["About 10 cm", "About 30 cm", "About 50 cm", "About 100 cm"], "ans": 2, "expJa": "バルク貨物室内の担当者が受け取りやすいよう、コンベア上の貨物には50cmくらいの間隔をあけるとテキストにある。", "expVi": "Giáo trình ghi để người trong khoang rời dễ nhận, hàng trên băng chuyền nên cách nhau khoảng 50cm.", "expEn": "The textbook says items on the conveyor are spaced about 50 cm apart so the loader in the bulk hold can take them easily."},
  {"id": "S2L20", "topic": "s2_load", "level": 2, "src": "SSW2テキスト 4-5-1 (p.45)", "qJa": "バルク貨物室内での積み込み方として正しいものはどれか？", "qVi": "Cách xếp hàng trong khoang hàng rời nào là đúng?", "qEn": "Which is the correct way to stow cargo in the bulk hold?", "optsJa": ["重いものほど上に積んで、全体を上から押さえる", "壊れやすい貨物はいちばん下に置く", "重いものは下に、壊れやすいものは上方に積む", "梱包同士は重ねず、すき間を残して積む"], "optsVi": ["Đồ nặng xếp lên trên để đè giữ toàn bộ", "Hàng dễ vỡ đặt ở dưới cùng", "Đồ nặng ở dưới, hàng dễ vỡ xếp phía trên", "Không chồng các kiện lên nhau, chừa khe hở"], "optsEn": ["Put heavier items on top to hold the rest down", "Place fragile items at the very bottom", "Heavy items below, fragile items higher up", "Do not overlap packages; leave gaps between"], "ans": 2, "expJa": "テキストでは、重いものほど下に、壊れやすい貨物は上方に積み込むとしている。また無駄なスペースを空けず、2つの梱包に重ねるように積んで安定させる。", "expVi": "Giáo trình yêu cầu đồ càng nặng càng để dưới, hàng dễ vỡ xếp phía trên; đồng thời không để khoảng trống thừa và xếp chồng lên hai kiện để tăng độ ổn định.", "expEn": "The textbook says heavier items go lower and fragile cargo higher. Space should not be wasted, and items are stacked across two packages for stability."},
  {"id": "S2L21", "topic": "s2_load", "level": 2, "src": "SSW2テキスト 4-5-3 (p.46)", "qJa": "バルク手荷物が多量の場合、テキストではどのように積むとされているか？", "qVi": "Khi hành lý rời nhiều, giáo trình hướng dẫn xếp như thế nào?", "qEn": "When there is a large amount of bulk baggage, how does the textbook say to stow it?", "optsJa": ["旅客に早く渡したい手荷物を手前に積む", "重い手荷物から順にドア付近に積む", "乗り継ぎ手荷物を最も奥にまとめて積む", "行き先に関係なく受け取った順に積む"], "optsVi": ["Hành lý cần trả khách sớm xếp phía ngoài", "Xếp hành lý nặng gần cửa theo thứ tự", "Gom hành lý nối chuyến xếp ở trong cùng", "Xếp theo thứ tự nhận, không xét điểm đến"], "optsEn": ["Put bags to be returned quickly nearest the door", "Put the heaviest bags nearest the door first", "Put transfer bags together at the very back", "Stow in order received, regardless of destination"], "ans": 0, "expJa": "手荷物が多い場合は到着地での取り降ろしを考え、旅客に早く手渡したい手荷物を手前に積むとされている。", "expVi": "Khi hành lý nhiều, phải nghĩ đến việc dỡ ở điểm đến và xếp hành lý cần trao sớm cho khách ở phía ngoài (手前).", "expEn": "With a lot of baggage, unloading at the destination is considered, so bags that should reach passengers quickly are stowed nearest the door."},
  {"id": "S2L22", "topic": "s2_load", "level": 2, "src": "SSW2テキスト 4-6-2 (p.48)", "qJa": "最低乗り継ぎ時間（MCT）についての説明として正しいものはどれか？", "qVi": "Mô tả nào đúng về thời gian nối chuyến tối thiểu (MCT)?", "qEn": "Which statement about the Minimum Connection Time (MCT) is correct?", "optsJa": ["国際線同士の乗り継ぎにだけ設定されている時間である", "航空会社ごとに全空港で共通の値として設定されている", "下回った場合でも手荷物は必ず予定便へ搭載される", "空港ごとに設定され、下回ると基本的に次便へ乗れない"], "optsVi": ["Chỉ được đặt cho nối chuyến giữa các chuyến bay quốc tế với nhau", "Mỗi hãng bay đặt một giá trị chung áp dụng cho tất cả sân bay", "Dù thấp hơn MCT, hành lý vẫn luôn được chất lên chuyến dự định", "Do từng sân bay đặt; thấp hơn thì về cơ bản không nối chuyến được"], "optsEn": ["It applies only to connections between two international flights", "Each airline sets one common value that applies at every airport", "Even below the MCT, bags always go on the originally planned flight", "Set by each airport; below it, a connection is basically impossible"], "ans": 3, "expJa": "MCTは各空港で設定された最低乗り継ぎ時間で、これを下回ると基本的に次便に乗り継げない。国内線・国際線のすべての組み合わせで設定されている。", "expVi": "MCT là thời gian nối chuyến tối thiểu do từng sân bay đặt ra; nếu thấp hơn thì về cơ bản không thể nối sang chuyến tiếp. MCT được đặt cho mọi tổ hợp nội địa/quốc tế.", "expEn": "MCT is the minimum connection time set at each airport; below it, a connection to the next flight is basically not possible. It is set for every domestic/international combination."},
  {"id": "S2L23", "topic": "s2_load", "level": 2, "src": "SSW2テキスト 4-6-3 (p.49)", "qJa": "到着便の作業準備は、いつまでにすべて完了しスポットで待機するとされているか？", "qVi": "Việc chuẩn bị cho chuyến bay đến phải hoàn tất và chờ ở vị trí đỗ (スポット) trước bao lâu?", "qEn": "By when must all preparations for an arriving flight be complete, with staff waiting at the spot?", "optsJa": ["到着便の10～5分前", "到着便の20～15分前", "到着便の30～25分前", "到着便の1分前"], "optsVi": ["10–5 phút trước khi đến", "20–15 phút trước khi đến", "30–25 phút trước khi đến", "1 phút trước khi đến"], "optsEn": ["10 to 5 minutes before arrival", "20 to 15 minutes before arrival", "30 to 25 minutes before arrival", "1 minute before arrival"], "ans": 0, "expJa": "テキストでは、到着便の10～5分前までにすべての準備を終え、スポットで待機するとしている。", "expVi": "Giáo trình quy định phải hoàn tất mọi chuẩn bị và chờ tại スポット trước khi chuyến bay đến 10–5 phút.", "expEn": "The textbook says all preparations are finished and staff wait at the spot by 10 to 5 minutes before arrival."},
  {"id": "S2L24", "topic": "s2_load", "level": 2, "src": "SSW2テキスト 4-7-1 (p.49)", "qJa": "出発便で、搭載監督者自身が一般的に実施している業務はどれか？", "qVi": "Đối với chuyến bay đi, công việc nào thường do chính giám sát chất xếp (搭載監督者) thực hiện?", "qEn": "On a departing flight, which task is generally done by the load master personally?", "optsJa": ["旅客のチェック・イン手続きと手荷物タグの発行", "バラ積み室での危険物・動物・WET貨物の搭載確認", "フライト・プランの作成と搭載燃料量の最終決定", "ハイリフト・ローダーの定期整備と点検記録の作成"], "optsVi": ["Làm thủ tục check-in cho khách và phát thẻ hành lý ký gửi", "Xác nhận chất hàng nguy hiểm, động vật, hàng ướt ở khoang rời", "Lập フライト・プラン và quyết định lượng nhiên liệu cuối cùng", "Bảo dưỡng định kỳ xe nâng hàng và lập hồ sơ kiểm tra"], "optsEn": ["Handling passenger check-in and issuing bag tags", "Checking DG, animals and wet cargo in bulk", "Making the flight plan and setting the fuel load", "Routine maintenance of high-lift loaders and logs"], "ans": 1, "expJa": "搭載監督者自身が行う業務として、タイダウンとゾーン・ローディングの確認、バラ積み貨物室での危険物・動物・WET貨物の搭載確認、ULD部分搭載省略時の緊締確認が挙げられている。", "expVi": "Các việc chính giám sát chất xếp tự làm gồm: xác nhận chằng buộc (タイダウン) và chất theo vùng, xác nhận chất hàng nguy hiểm, động vật, hàng ướt ở khoang rời, và xác nhận cố định khi bỏ qua chất một phần ULD.", "expEn": "Tasks the load master does personally include checking tie-downs and zone loading, checking DG, animals and wet cargo in the bulk hold, and checking restraint when partial ULD loading is omitted."},
  {"id": "S2L25", "topic": "s2_load", "level": 2, "src": "SSW2テキスト 4-8-3 (p.52)", "qJa": "ボーイング777のパッセンジャー・ドアに装備されたEPASは、緊急時に機内からドアを開く操作を何で補助するか？", "qVi": "Hệ thống EPAS trên cửa hành khách Boeing 777 hỗ trợ mở cửa từ bên trong khi khẩn cấp bằng gì?", "qEn": "On the Boeing 777 passenger door, what does EPAS use to assist opening from inside in an emergency?", "optsJa": ["油圧ポンプの力", "電動モーターの力", "圧縮空気の圧力", "窒素ガスの圧力"], "optsVi": ["Lực của bơm thủy lực", "Lực động cơ điện", "Áp suất khí nén", "Áp suất khí nitơ"], "optsEn": ["Hydraulic pump power", "Electric motor power", "Compressed air pressure", "Nitrogen gas pressure"], "ans": 3, "expJa": "B777のドアにはEmergency Power Assist System（EPAS）があり、緊急時の機内からのドア開放を窒素ガスの圧力で助ける。", "expVi": "Cửa B777 có Emergency Power Assist System (EPAS), dùng áp suất khí nitơ để hỗ trợ mở cửa từ bên trong khi khẩn cấp.", "expEn": "The B777 door has an Emergency Power Assist System (EPAS) that uses nitrogen gas pressure to help open the door from inside in an emergency."},
  {"id": "S2L26", "topic": "s2_load", "level": 2, "src": "SSW2テキスト 4-8-4 (p.52)", "qJa": "パッセンジャー・ドアのモードセレクトレバーについて、正しいものはどれか？", "qVi": "Về cần chọn chế độ (モードセレクトレバー) của cửa hành khách, câu nào đúng?", "qEn": "Which statement about the passenger door mode select lever is correct?", "optsJa": ["「Armed」で開けるとスライドが自動で外へ展開する", "「Disarmed」で開けるとスライドが自動で展開する", "地上での駐機中は通常「Armed」にセットされる", "駐機中のドア操作ではモード確認は必要ない"], "optsVi": ["Mở cửa ở \"Armed\" thì cầu trượt tự bung ra ngoài", "Mở cửa ở \"Disarmed\" thì cầu trượt sẽ tự bung ra", "Khi đỗ trên mặt đất thường được đặt ở \"Armed\"", "Khi đỗ, thao tác cửa không cần kiểm tra chế độ"], "optsEn": ["Opening in Armed makes the slide deploy outward", "Opening in Disarmed makes the slide deploy outward", "It is normally set to Armed while parked", "No mode check is needed when parked"], "ans": 0, "expJa": "「Armed」の状態でドアを開くと同時にエスケープ・スライドが外側へ自動展開する。駐機中は通常「Disarmed」だが、操作前には必ずドアモードを確認する必要がある。", "expVi": "Ở chế độ \"Armed\", mở cửa thì cầu trượt thoát hiểm (エスケープ・スライド) tự bung ra ngoài. Khi đỗ thường để \"Disarmed\", nhưng trước khi thao tác vẫn bắt buộc kiểm tra chế độ cửa.", "expEn": "In Armed mode, opening the door automatically deploys the escape slide outward. When parked it is normally Disarmed, but the door mode must always be checked before operating it."},
  {"id": "S2G01", "topic": "s2_gse", "level": 2, "src": "SSW2テキスト 5-1-2 (p.55)", "qJa": "テキストの例で、ボーイング777-300の国内線駐機時間を50分とした場合、No.1クリーニングに充てられる時間はおよそ何分か？", "qVi": "Theo ví dụ trong giáo trình, nếu thời gian đỗ của Boeing 777-300 trên tuyến nội địa là 50 phút, thời gian dành cho vệ sinh No.1 (ターンアラウンド・クリーニング) là khoảng bao nhiêu?", "qEn": "In the textbook example, if a domestic Boeing 777-300 is parked for 50 minutes, about how much time is available for No.1 cleaning?", "optsJa": ["約10分", "約30分", "約20分", "約40分"], "optsVi": ["Khoảng 10 phút", "Khoảng 30 phút", "Khoảng 20 phút", "Khoảng 40 phút"], "optsEn": ["About 10 minutes", "About 30 minutes", "About 20 minutes", "About 40 minutes"], "ans": 2, "expJa": "到着旅客の降機に約10分、次便旅客の搭乗に約20分を要するため、50分のうち清掃に使えるのは約20分程度しかない。", "expVi": "Hành khách xuống máy bay mất khoảng 10 phút và hành khách chuyến sau lên máy bay mất khoảng 20 phút, nên trong 50 phút chỉ còn khoảng 20 phút để vệ sinh.", "expEn": "Deplaning takes about 10 minutes and boarding the next flight about 20 minutes, so only about 20 of the 50 minutes remain for cleaning."},
  {"id": "S2G02", "topic": "s2_gse", "level": 2, "src": "SSW2テキスト 5-1-3 (p.55)", "qJa": "No.2クリーニング（オーバーナイト作業）の説明として正しいものはどれか？", "qVi": "Mô tả nào sau đây về vệ sinh No.2 (オーバーナイト作業) là đúng?", "qEn": "Which description of No.2 cleaning (overnight work) is correct?", "optsJa": ["運航終了後に1日1回、真空掃除機での清掃と消毒を加えて行う", "便間ごとに毎回、座席とゴミの処理だけを短時間で済ませる", "定例整備に合わせ、シート・カバー交換や貨物室清掃まで行う", "月に1回、機体外部の洗浄作業とあわせて外部業者が行う"], "optsVi": ["Làm 1 lần/ngày sau khi kết thúc bay, thêm hút bụi thảm và khử trùng", "Làm mỗi lần giữa các chuyến, chỉ xử lý ghế và rác trong thời gian ngắn", "Làm cùng đợt bảo dưỡng định kỳ, gồm cả thay bọc ghế và vệ sinh khoang hàng", "Làm 1 lần/tháng do nhà thầu ngoài thực hiện cùng với rửa thân máy bay"], "optsEn": ["Done once a day after operations, adding carpet vacuuming and disinfection", "Done between every flight, quickly handling only seats and trash", "Done with scheduled maintenance, including seat cover changes and cargo hold cleaning", "Done monthly by an outside contractor together with exterior washing"], "ans": 0, "expJa": "No.2クリーニングは夜間駐機時などに1日1回実施され、No.1の内容に真空掃除機によるカーペット清掃と消毒が加わる。一機あたり約1時間かかる。", "expVi": "Vệ sinh No.2 làm 1 lần mỗi ngày khi máy bay đỗ qua đêm; ngoài nội dung của No.1 còn thêm hút bụi thảm và khử trùng, mất khoảng 1 giờ mỗi máy bay.", "expEn": "No.2 cleaning is done once a day, e.g. during overnight parking; it adds carpet vacuuming and disinfection to the No.1 tasks and takes about one hour per aircraft."},
  {"id": "S2G03", "topic": "s2_gse", "level": 2, "src": "SSW2テキスト 5-1-6 (p.56-57)", "qJa": "機内クリーニング中に旅客の忘れ物を見つけ、キャビン・アテンダントや旅客担当者に届ける際、確認のために報告することが大切とされているのは何か？", "qVi": "Khi tìm thấy đồ khách bỏ quên lúc vệ sinh và giao cho tiếp viên hoặc nhân viên phục vụ hành khách, điều quan trọng cần báo cáo để xác nhận là gì?", "qEn": "When a lost item found during cabin cleaning is handed to a cabin attendant or passenger agent, what is important to report for confirmation?", "optsJa": ["発見した作業者の社員番号と所属部署", "忘れ物のおおよその金額と重さ", "持ち主と思われる旅客の搭乗券の番号", "発見場所（15Aシート・ポケット等）"], "optsVi": ["Mã nhân viên và bộ phận của người tìm thấy", "Giá trị ước tính và trọng lượng của món đồ", "Số thẻ lên máy bay của hành khách có thể là chủ", "Vị trí tìm thấy (ví dụ: túi ghế 15A)"], "optsEn": ["Employee number and unit of the finder", "Approximate value and weight of the item", "Boarding pass number of the likely owner", "The spot found (e.g. seat pocket 15A)"], "ans": 3, "expJa": "忘れ物は旅客が空港内にいるうちに早く返せるよう届け、その際に発見場所を報告して確認できるようにすることが大切とされている。", "expVi": "Đồ bỏ quên cần được chuyển nhanh để trả lại khi khách còn ở sân bay, và phải báo vị trí tìm thấy để xác nhận.", "expEn": "Lost items should be passed on quickly so they can be returned while the passenger is still at the airport, and the location where it was found should be reported for confirmation."},
  {"id": "S2G04", "topic": "s2_gse", "level": 2, "src": "SSW2テキスト 5-2-2 (p.57-58)", "qJa": "フード・ローダーの荷台を上昇させる際、荷台の床を客室の床より低い位置（約19cm程度）で止める理由は何か？", "qVi": "Khi nâng sàn xe nâng suất ăn (フード・ローダー), vì sao phải dừng sàn thấp hơn sàn khoang khách (khoảng 19cm)?", "qEn": "When raising a food loader's body, why is its floor stopped below the cabin floor level (about 19 cm)?", "optsJa": ["車両の浮き沈みを抑えて、アウトリガーを不要にするため", "搭載で機体が沈み、ドアが荷台に当たって傷むのを防ぐため", "カートを機内へ押し込む際に勢いをつけやすくするため", "機内の冷暖房の空気が外へ逃げにくくなるようにするため"], "optsVi": ["Để hạn chế xe nhấp nhô, không cần dùng chân chống (アウトリガー)", "Để cửa không va vào sàn xe khi máy bay lún do chất tải", "Để dễ lấy đà khi đẩy xe đẩy (カート) vào trong máy bay", "Để không khí điều hòa trong cabin khó thoát ra ngoài"], "optsEn": ["To reduce vehicle bounce so the outriggers are not needed", "So the door won't hit the platform as the aircraft settles", "To make it easier to build momentum when pushing carts inside", "To keep the cabin's conditioned air from escaping outside"], "ans": 1, "expJa": "貨物や燃料を搭載すると機体が沈み込み、外開きのドアが荷台の床に接触して損傷するおそれがあるため、荷台をやや低い位置で止める。", "expVi": "Khi chất hàng hoặc nạp nhiên liệu, thân máy bay lún xuống và cửa mở ra ngoài có thể chạm sàn xe gây hư hỏng, nên phải dừng sàn xe ở vị trí hơi thấp.", "expEn": "Loading cargo or fuel makes the aircraft settle, and the outward-opening door could strike the platform and be damaged, so the platform is stopped slightly lower."},
  {"id": "S2G05", "topic": "s2_gse", "level": 2, "src": "SSW2テキスト 5-3 (p.59)", "qJa": "国際線の機内と機用品の取り扱いについて、テキストの記述として正しいものはどれか？", "qVi": "Về khoang máy bay tuyến quốc tế và việc xử lý vật phẩm, nội dung nào đúng theo giáo trình?", "qEn": "According to the textbook, which statement about international aircraft cabins and cabin supplies is correct?", "optsJa": ["税関上は国内と同じ扱いで、酒やタバコも自由に持ち出せる", "税関上は外国と同じ扱いで、指定の経路・方法で積み降ろす", "税関の規制は旅客だけに適用され、作業者は対象とならない", "空き缶やゴミは税関と関係なく、一般ゴミとして処理できる"], "optsVi": ["Về hải quan được coi như trong nước, có thể tự do mang rượu, thuốc lá ra", "Hải quan coi như nước ngoài, phải bốc dỡ theo tuyến và cách chỉ định", "Quy định hải quan chỉ áp dụng cho hành khách, không áp dụng cho nhân viên", "Lon rỗng và rác không liên quan hải quan, xử lý như rác thông thường"], "optsEn": ["For customs it counts as domestic, so liquor and tobacco may be taken out freely", "Customs treats it as foreign; use the designated routes and methods", "Customs rules apply only to passengers, not to ground workers", "Empty cans and trash have no customs issue and go out as normal waste"], "ans": 1, "expJa": "国際線の機内は税関上外国と同じに扱われ、国内用品は税関長が指定した経路・方法で積み降ろさないと関税法違反になる。タバコや酒を持ち出せば密輸となり、ゴミも決められた方法で処理する。", "expVi": "Khoang máy bay quốc tế được hải quan coi như nước ngoài; nếu không bốc dỡ theo tuyến và cách do trưởng hải quan chỉ định thì vi phạm Luật Hải quan. Mang thuốc lá, rượu ra là buôn lậu, rác cũng phải xử lý đúng quy định.", "expEn": "An international cabin is treated as foreign territory for customs; not following the routes and methods set by the customs director violates the Customs Act. Taking out tobacco or liquor counts as smuggling, and trash must be handled as prescribed."},
  {"id": "S2G06", "topic": "s2_gse", "level": 2, "src": "SSW2テキスト 6-1-1 (p.60)", "qJa": "「クリーン・エアクラフト・コンセプト」の意味として正しいものはどれか？", "qVi": "\"Clean Aircraft Concept\" (クリーン・エアクラフト・コンセプト) có nghĩa là gì?", "qEn": "What does the \"clean aircraft concept\" mean?", "optsJa": ["便間ごとに客室を清掃し、機内の美観と衛生を保つこと", "洗浄作業車を使って、定期的に機体の外部を洗浄すること", "防除氷装置を備えた航空機だけを寒冷地の路線で運航すること", "設計上の装備以外の物が付着した状態で飛行させないこと"], "optsVi": ["Vệ sinh khoang khách giữa các chuyến để giữ sạch đẹp và vệ sinh", "Dùng xe rửa để rửa bên ngoài thân máy bay định kỳ", "Chỉ khai thác máy bay có thiết bị chống/phá băng trên tuyến vùng lạnh", "Không cho máy bay bay khi còn bám vật gì ngoài thiết bị theo thiết kế"], "optsEn": ["Cleaning the cabin between flights to keep it tidy and hygienic", "Washing the aircraft exterior regularly with washing vehicles", "Flying only aircraft with ice protection systems on cold routes", "Not flying with anything attached other than designed parts"], "ans": 3, "expJa": "雪や氷が付いたまま離陸すると推力低下や揚力減少などの悪影響が出るため、設計上取り付けられた物以外が付着した状態で飛行させないという考え方である。", "expVi": "Cất cánh khi còn tuyết, băng bám sẽ gây giảm lực đẩy, giảm lực nâng…, nên nguyên tắc là không bay khi có vật bám ngoài những gì được lắp theo thiết kế.", "expEn": "Taking off with snow or ice causes thrust loss, lift loss and other effects, so the rule is not to fly with anything attached other than what the design includes."},
  {"id": "S2G07", "topic": "s2_gse", "level": 2, "src": "SSW2テキスト 6-1-2 (p.60)", "qJa": "除雪氷液（デアイシング・フルード）は水で希釈したうえで何℃以上に加熱して使用するか？", "qVi": "Dung dịch phá băng (デアイシング・フルード) sau khi pha loãng với nước được làm nóng lên từ bao nhiêu ℃ trở lên?", "qEn": "After dilution with water, to what temperature or higher is de-icing fluid heated?", "optsJa": ["60℃以上", "40℃以上", "80℃以上", "100℃以上"], "optsVi": ["Từ 60℃ trở lên", "Từ 40℃ trở lên", "Từ 80℃ trở lên", "Từ 100℃ trở lên"], "optsEn": ["60°C or higher", "40°C or higher", "80°C or higher", "100°C or higher"], "ans": 0, "expJa": "除雪氷液は水で薄めて60℃以上に温め、雪や氷を溶かして除去する。厚い氷は機体表面を温めて下から溶かすと効果的にはがせる。", "expVi": "Dung dịch phá băng được pha loãng rồi làm nóng từ 60℃ trở lên để làm tan tuyết, băng. Băng dày thì làm ấm bề mặt thân để tan từ bên dưới rồi bóc ra sẽ hiệu quả.", "expEn": "The fluid is diluted and heated to at least 60°C to melt snow and ice; thick ice is removed best by warming the surface so it melts from below."},
  {"id": "S2G08", "topic": "s2_gse", "level": 2, "src": "SSW2テキスト 7-1-1 (p.61-62)", "qJa": "トーバーレス・トラクターについて、テキストの記述として正しいものはどれか？", "qVi": "Về xe kéo không thanh kéo (トーバーレス・トラクター), nội dung nào đúng theo giáo trình?", "qEn": "According to the textbook, which statement about towbarless tractors is correct?", "optsJa": ["トーバーを介してノーズ・ギアに接続する、押し出し専用車である", "2000年代後半に導入された、小型機だけに使える車両である", "脚を直接抱え込み、使用には機体メーカーの承認が必要である", "性能上の速度は時速15km/hで、トーバー式よりも低速である"], "optsVi": ["Nối với càng mũi qua thanh kéo, là xe chuyên dùng để đẩy lùi", "Được đưa vào cuối những năm 2000, chỉ dùng được cho máy bay nhỏ", "Ôm trực tiếp càng máy bay, cần hãng chế tạo máy bay chấp thuận", "Tốc độ theo tính năng là 15km/h, chậm hơn loại dùng thanh kéo"], "optsEn": ["It connects to the nose gear via a towbar and is used only for pushback", "It was introduced in the late 2000s and works only with small aircraft", "It clamps the gear directly and needs approval from the aircraft maker", "Its rated speed is 15 km/h, slower than the towbar type"], "ans": 2, "expJa": "トーバーレス・トラクターはノーズ（またはメイン）・ランディング・ギアを直接抱え込み、トーバー式より高速（性能上30km/h）で牽引できる。使用には当該機体メーカーの承認が要る。1990年代に導入された。", "expVi": "Xe kéo không thanh kéo ôm trực tiếp càng mũi (hoặc càng chính), kéo nhanh hơn loại có thanh kéo (theo tính năng 30km/h). Khi sử dụng cần hãng sản xuất máy bay chấp thuận; loại xe này được đưa vào từ những năm 1990.", "expEn": "A towbarless tractor clamps the nose (or main) gear directly and can tow faster than the towbar type (30 km/h rated). Its use requires the aircraft manufacturer's approval; it was introduced in the 1990s."},
  {"id": "S2G09", "topic": "s2_gse", "level": 2, "src": "SSW2テキスト 7-1-4 (p.63)", "qJa": "ダミー・シップを使ったトーイング訓練では、旋回角度を何度以下とするか？", "qVi": "Khi huấn luyện kéo máy bay bằng máy bay giả (ダミー・シップ), góc quay vòng phải từ bao nhiêu độ trở xuống?", "qEn": "In towing training with a dummy ship, the turning angle must be kept at or below what?", "optsJa": ["45°", "30°", "60°", "90°"], "optsVi": ["45°", "30°", "60°", "90°"], "optsEn": ["45°", "30°", "60°", "90°"], "ans": 0, "expJa": "ダミー・シップでの訓練は実機の牽引を模擬するため、急な発進・停止はできるだけ避け、旋回角度は45°以下とする。", "expVi": "Vì mô phỏng việc kéo máy bay thật, khi huấn luyện với máy bay giả cần tránh khởi động, dừng đột ngột và giữ góc quay vòng từ 45° trở xuống.", "expEn": "Because dummy ship training simulates real towing, sudden starts and stops are avoided and turns are limited to 45° or less."},
  {"id": "S2G10", "topic": "s2_gse", "level": 2, "src": "SSW2テキスト 7-2-1 (p.63-64)", "qJa": "パッセンジャー・ステップ車が航空機に向かって走行するとき、航空機まで5m以内での速度制限はどれか？", "qVi": "Khi xe thang hành khách (パッセンジャー・ステップ車) chạy về phía máy bay, giới hạn tốc độ trong phạm vi 5m là bao nhiêu?", "qEn": "When a passenger step vehicle drives toward an aircraft, what is the speed limit within 5 m of it?", "optsJa": ["15km/h以下", "8km/h以下", "5km/h以下", "10km/h以下"], "optsVi": ["Từ 15km/h trở xuống", "Từ 8km/h trở xuống", "Từ 5km/h trở xuống", "Từ 10km/h trở xuống"], "optsEn": ["15 km/h or less", "8 km/h or less", "5 km/h or less", "10 km/h or less"], "ans": 1, "expJa": "制限区域内は30km/h以下で、航空機に向かって30m以内は15km/h以下、5m以内は8km/h以下に制限されている。", "expVi": "Trong khu vực hạn chế tốc độ tối đa là 30km/h; khi tiến về máy bay, trong 30m là 15km/h trở xuống và trong 5m là 8km/h trở xuống.", "expEn": "In the restricted area the limit is 30 km/h; approaching an aircraft it is 15 km/h within 30 m and 8 km/h within 5 m."},
  {"id": "S2G11", "topic": "s2_gse", "level": 2, "src": "SSW2テキスト 7-2-1 b (p.64)", "qJa": "自走式クルー・ステップで、左折時に時速5km以下まで速度を落とさなければならない理由はどれか？", "qVi": "Với thang tổ bay tự hành (クルー・ステップ), vì sao khi rẽ trái phải giảm tốc xuống 5km/h trở xuống?", "qEn": "Why must a self-propelled crew step slow to 5 km/h or less when turning left?", "optsJa": ["左側に固定橋が多く、車両の高さでは下を通過できないため", "左側の後方カメラの視界が狭く、誘導者の合図が必要なため", "左折時は外輪差が特に大きく、機体の翼に接触しやすいため", "重心が車体の左上にあり、左折時に横転しやすいため"], "optsVi": ["Bên trái có nhiều cầu cố định, chiều cao xe không đi qua bên dưới được", "Camera lùi phía trái có tầm nhìn hẹp, cần người dẫn đường ra hiệu", "Khi rẽ trái độ lệch bánh ngoài rất lớn, dễ va vào cánh máy bay", "Trọng tâm xe nằm phía trên bên trái, dễ lật khi rẽ trái"], "optsEn": ["There are many fixed bridges on the left that the tall vehicle cannot pass", "The left rear camera has a narrow view, so a guide's signals are needed", "Left turns create a large outer wheel offset, so it easily hits a wing", "Its center of gravity is high on the left, so it can tip over"], "ans": 3, "expJa": "クルー・ステップは運転席が車体左側上部にあり重心が左上に寄っているため、左折時に5km/h以下に落とさないと横転の危険が高い。急ブレーキや急ハンドルも厳禁である。", "expVi": "Thang tổ bay có ghế lái ở phía trên bên trái nên trọng tâm lệch lên trái; nếu không giảm xuống 5km/h trở xuống khi rẽ trái thì nguy cơ lật rất cao. Phanh gấp, đánh lái gấp cũng bị cấm.", "expEn": "The crew step's cab is at the upper left, shifting its center of gravity there, so it risks tipping over unless slowed to 5 km/h on left turns. Hard braking and sharp steering are prohibited."},
  {"id": "S2G12", "topic": "s2_gse", "level": 2, "src": "SSW2テキスト 7-2-2 (p.65)", "qJa": "パッセンジャー・ボーディング・ブリッジ（PBB）の整備について、正しいものはどれか？", "qVi": "Về bảo dưỡng ống lồng PBB (搭乗橋), nội dung nào đúng?", "qEn": "Which statement about maintenance of the passenger boarding bridge (PBB) is correct?", "optsJa": ["分解を伴わない整備は、航空機に装着した状態で実施する", "重整備を含むすべての整備を、運用中に並行して実施する", "分解を伴う重整備は、PBBの使用を一時停止して実施する", "整備は、操作資格を持つ旅客係員であれば誰でも実施できる"], "optsVi": ["Bảo dưỡng không tháo rời được làm khi PBB đang nối với máy bay", "Mọi bảo dưỡng, kể cả bảo dưỡng lớn, đều làm song song khi đang khai thác", "Bảo dưỡng lớn có tháo rời được làm sau khi tạm dừng sử dụng PBB", "Bất kỳ nhân viên hành khách nào có chứng chỉ vận hành đều bảo dưỡng được"], "optsEn": ["Maintenance without disassembly is done while docked to an aircraft", "All maintenance, including heavy work, is done during normal operation", "Heavy maintenance with disassembly is done after suspending PBB use", "Any passenger agent with an operating license may perform maintenance"], "ans": 2, "expJa": "PBBの整備は設備や非常時対応に精通した作業者が行い、分解を伴わない整備は使用されていない時間帯に、分解を伴う重整備は使用を一時停止させて行う。", "expVi": "Bảo dưỡng PBB do người am hiểu thiết bị và cách xử lý khẩn cấp thực hiện; loại không tháo rời làm vào giờ PBB không dùng, còn bảo dưỡng lớn có tháo rời thì tạm dừng sử dụng PBB.", "expEn": "PBB maintenance is done by workers who know the equipment and emergency response; work without disassembly is done when the PBB is not in use, and heavy work with disassembly requires suspending its use."},
  {"id": "S2G13", "topic": "s2_gse", "level": 2, "src": "SSW2テキスト 7-2-3 (p.65)", "qJa": "カーゴ・ローダー（高速搬送ローダーを除く）の速度制限はどれか？", "qVi": "Giới hạn tốc độ của xe nâng hàng (カーゴ・ローダー), trừ loại vận chuyển tốc độ cao, là bao nhiêu?", "qEn": "What is the speed limit for cargo loaders, excluding high-speed transport loaders?", "optsJa": ["8km/h", "15km/h", "30km/h", "20km/h"], "optsVi": ["8km/h", "15km/h", "30km/h", "20km/h"], "optsEn": ["8 km/h", "15 km/h", "30 km/h", "20 km/h"], "ans": 1, "expJa": "カーゴ・ローダーの速度制限は15km/hで、高速搬送ローダーは30km/hとされている。晴天時でも移送装置の回転中は乗ってはならない。", "expVi": "Giới hạn tốc độ của xe nâng hàng là 15km/h, còn loại vận chuyển tốc độ cao là 30km/h. Kể cả trời nắng cũng không được đứng lên khi bộ phận chuyển tải đang quay.", "expEn": "Cargo loaders are limited to 15 km/h, and high-speed transport loaders to 30 km/h. Even in fair weather, do not step on the transfer system while it is moving."},
  {"id": "S2G14", "topic": "s2_gse", "level": 2, "src": "SSW2テキスト 7-2-3 c (p.66)", "qJa": "ベルト・ローダーのベルトの長さとしてテキストに示されている2種類はどれか？", "qVi": "Giáo trình nêu 2 loại chiều dài băng chuyền của xe băng tải (ベルト・ローダー) là gì?", "qEn": "Which two belt lengths does the textbook give for belt loaders?", "optsJa": ["7mと4m", "10mと5m", "6mと3m", "8mと5m"], "optsVi": ["7m và 4m", "10m và 5m", "6m và 3m", "8m và 5m"], "optsEn": ["7 m and 4 m", "10 m and 5 m", "6 m and 3 m", "8 m and 5 m"], "ans": 0, "expJa": "ベルト・ローダーはエンジン駆動の油圧ポンプでベルトを回し、バルク貨物室に貨物や手荷物を積み降ろす車両で、ベルト長は7mと4mの2種類がある。", "expVi": "Xe băng tải quay băng chuyền bằng bơm thủy lực do động cơ dẫn động, dùng để bốc dỡ hàng, hành lý ở khoang hàng rời; chiều dài băng có 2 loại 7m và 4m.", "expEn": "A belt loader turns its belt with an engine-driven hydraulic pump to load bulk holds with cargo and baggage; belts come in two lengths, 7 m and 4 m."},
  {"id": "S2G15", "topic": "s2_gse", "level": 2, "src": "SSW2テキスト 7-2-4 (p.67)", "qJa": "構内運転のフォークリフトで、技能講習修了済の免許証を持っていなければ荷役作業に従事できないのは、最大荷重がいくら以上の車両か？", "qVi": "Với xe nâng (フォークリフト) chạy trong khu vực, xe có tải trọng tối đa từ bao nhiêu trở lên thì phải có chứng chỉ hoàn thành khóa kỹ năng mới được làm công việc bốc xếp?", "qEn": "For forklifts driven on premises, from what maximum load is a skill-training completion certificate required for cargo handling?", "optsJa": ["0.5トン以上", "2トン以上", "1トン以上", "3トン以上"], "optsVi": ["Từ 0,5 tấn trở lên", "Từ 2 tấn trở lên", "Từ 1 tấn trở lên", "Từ 3 tấn trở lên"], "optsEn": ["0.5 tons or more", "2 tons or more", "1 ton or more", "3 tons or more"], "ans": 2, "expJa": "構内運転では、最大荷重1トン以上のフォークリフトは技能講習を修了した免許証がなければ荷役作業に就けない。", "expVi": "Khi chạy trong khu vực, xe nâng có tải trọng tối đa từ 1 tấn trở lên đòi hỏi phải có chứng chỉ hoàn thành khóa kỹ năng mới được bốc xếp.", "expEn": "On premises, forklifts with a maximum load of 1 ton or more may be used for cargo handling only by holders of a skill-training completion certificate."},
  {"id": "S2G16", "topic": "s2_gse", "level": 2, "src": "SSW2テキスト 7-2-5 (p.67-68)", "qJa": "テール・サポート・スタンションの取り扱いについて、誤っているものはどれか？", "qVi": "Về cách sử dụng giá đỡ đuôi (テール・サポート・スタンション), nội dung nào KHÔNG đúng?", "qEn": "Which statement about handling a tail support stanchion is NOT correct?", "optsJa": ["牽引前に、シリンダーが最も下がった状態であることを確かめる", "牽引は2人で行い、時速5km/h以下の速度で移動させる", "上部踊り場から装着状況を確認するときは、安全ベルトを着ける", "尾部へは左側から近づき、牽引車のまま尾部の下まで入れる"], "optsVi": ["Trước khi kéo, xác nhận xi lanh đã hạ xuống thấp nhất", "Kéo do 2 người thực hiện, di chuyển với tốc độ từ 5km/h trở xuống", "Khi kiểm tra tình trạng lắp từ sàn nghỉ phía trên, phải đeo dây an toàn", "Tiếp cận đuôi từ bên trái và để nguyên xe kéo đưa vào dưới đuôi"], "optsEn": ["Before towing, confirm the cylinder is fully lowered", "Towing is done by two people at 5 km/h or less", "Wear a safety belt when checking the fitting from the upper landing", "Approach from the left and tow it right under the tail"], "ans": 3, "expJa": "テキストでは、尾部へは右側から接近し、途中で牽引車から切り離して尾部下までは人力で移動するとされている。そのほかの選択肢はテキストの注意事項どおりである。", "expVi": "Theo giáo trình, phải tiếp cận đuôi từ bên phải, tháo khỏi xe kéo giữa chừng rồi đẩy bằng tay đến dưới đuôi. Các lựa chọn còn lại đúng với lưu ý trong giáo trình.", "expEn": "The textbook says to approach the tail from the right, detach from the tow vehicle partway, and move it under the tail by hand. The other options match the textbook's precautions."},
  {"id": "S2G17", "topic": "s2_gse", "level": 2, "src": "SSW2テキスト 7-2-6 (p.68)", "qJa": "ノーズ・テザーリング・デバイスのスリングの扱いとして正しいものはどれか？", "qVi": "Cách xử lý dây treo (スリング) của thiết bị neo càng mũi (ノーズ・テザーリング・デバイス) nào là đúng?", "qEn": "Which is the correct way to handle the slings of a nose tethering device?", "optsJa": ["装着状態で、前脚の左右に均等な緩みを持たせておく", "緩みが出ないよう、できるだけ強く張った状態で固定する", "ずれを防ぐため、脚の配線用導管に掛けて固定する", "左右どちらか片側のアンカーだけに掛けて固定する"], "optsVi": ["Để độ chùng đều ở hai bên càng mũi khi lắp", "Cố định ở trạng thái căng hết mức để không bị chùng", "Móc vào ống dẫn dây điện của càng để chống xê dịch", "Chỉ móc vào neo ở một bên, trái hoặc phải, của càng"], "optsEn": ["Leave equal slack on both sides of the nose gear", "Fix them pulled as tight as possible so there is no slack", "Hook them over the gear's wiring conduit to stop slipping", "Attach them to the anchor on only one side"], "ans": 0, "expJa": "スリングは配線用導管に掛からず、よじれないように前脚を左右のアンカーに繋留し、左右で均等に緩みを持たせる。搭降載中は張りすぎに注意する。", "expVi": "Neo càng mũi vào các neo hai bên sao cho dây không mắc vào ống dẫn dây điện và không bị xoắn, để độ chùng đều hai bên; trong lúc bốc dỡ chú ý không để dây quá căng.", "expEn": "The nose gear is tied to anchors on both sides without the sling catching the wiring conduit or twisting, with equal slack each side; during loading, take care that it does not get too tight."},
  {"id": "S2G18", "topic": "s2_gse", "level": 2, "src": "SSW2テキスト 7-4-5 (p.73)", "qJa": "排水車が使用される目的として正しいものはどれか？", "qVi": "Mục đích sử dụng xe xả nước (排水車) nào là đúng?", "qEn": "What is the drain water vehicle used for?", "optsJa": ["汚水タンクから汚水を抜き取り、タンク内を洗浄するため", "1日以上置けない飲料水を、夜間の入れ替え時に抜くため", "除雪氷液で濡れたランプ路面の水をまとめて回収するため", "機体洗浄作業で出た汚れた水を、地上で回収するため"], "optsVi": ["Để hút nước thải từ bồn nước thải và rửa bên trong bồn", "Để rút nước uống (không trữ quá 1 ngày) khi thay ban đêm", "Để thu gom nước trên mặt sân đỗ bị ướt do dung dịch phá băng", "Để thu hồi nước bẩn phát sinh khi rửa thân máy bay"], "optsEn": ["To remove waste from the waste tank and wash out the tank", "To drain drinking water during the nightly water change", "To collect liquid from ramp surfaces wet with de-icing fluid", "To recover dirty water left over from aircraft washing"], "ans": 1, "expJa": "機内の飲料水は1日以上溜めておけないため夜間に入れ替え、その際に抜いた水を受ける排水タンク付きの自走車両が排水車である。777就航で排水口が高くなり、リフト装置を備える。", "expVi": "Nước uống trên máy bay không được trữ quá 1 ngày nên được thay vào ban đêm; xe xả nước là xe tự hành có bồn chứa để rút nước khi thay. Do cửa xả của 777 cao hơn nên xe có thiết bị nâng.", "expEn": "Onboard drinking water cannot be stored over a day, so it is replaced at night; the drain vehicle is a self-propelled truck with a tank that receives it. It has a lift because the 777's drain port is higher."},
  {"id": "S2G19", "topic": "s2_gse", "level": 2, "src": "SSW2テキスト 7-4-7 a (p.74)", "qJa": "比較的大型の冷蔵設備をもつエア・コンディショニング・カーが高圧ガス保安法の規制対象となる場合に必要とされることはどれか？", "qVi": "Khi xe điều hòa (エア・コンディショニング・カー) có thiết bị làm lạnh khá lớn chịu sự điều chỉnh của Luật An toàn khí áp cao, điều gì là bắt buộc?", "qEn": "When an air-conditioning car with a fairly large refrigeration unit falls under the High Pressure Gas Safety Act, what is required?", "optsJa": ["運転者全員が大型特殊免許を取り、3年ごとに更新を受ける", "使用のたびに航空会社の整備士が立ち会い、点検を行う", "公的な保安検査は不要で、オペレーターの自主点検で足りる", "1台ごとに保安責任者1人を選び、毎年保安教育を行う"], "optsVi": ["Tất cả lái xe phải có bằng xe đặc chủng cỡ lớn và gia hạn 3 năm một lần", "Mỗi lần sử dụng phải có thợ máy của hãng bay chứng kiến và kiểm tra", "Không cần kiểm tra an toàn chính thức, chỉ cần người vận hành tự kiểm tra", "Mỗi xe có 1 người phụ trách an toàn, đào tạo an toàn hằng năm"], "optsEn": ["All drivers hold a large special license, renewed every three years", "An airline mechanic must attend and inspect each time it is used", "No official inspection is needed; operator self-checks are enough", "One safety manager per vehicle; yearly operator safety training"], "ans": 3, "expJa": "高圧ガス保安法の規制を受ける場合、一台につき1人の保安責任者の選出とオペレーターへの毎年の保安教育が必要で、定期的な高圧ガス保安検査も受けなければならない。", "expVi": "Nếu chịu Luật An toàn khí áp cao thì mỗi xe phải chọn 1 người phụ trách an toàn, đào tạo an toàn hằng năm cho người vận hành và phải kiểm tra an toàn khí áp cao định kỳ.", "expEn": "Under the High Pressure Gas Safety Act, each vehicle needs one appointed safety manager, operators need yearly safety training, and periodic high-pressure gas inspections are also required."},
  {"id": "S2G20", "topic": "s2_gse", "level": 2, "src": "SSW2テキスト 7-4-7 b (p.75)", "qJa": "地上空調気供給設備で冷房を行う際、冷水コイルを出た空気を冷凍装置でさらに何℃まで冷却するか？", "qVi": "Ở hệ thống cấp khí điều hòa mặt đất, khi làm lạnh, không khí ra khỏi cuộn nước lạnh được thiết bị làm lạnh hạ tiếp xuống bao nhiêu ℃?", "qEn": "In the ground air-conditioning supply system, to what temperature is air leaving the chilled-water coil further cooled for cooling?", "optsJa": ["6℃", "0℃", "－2℃", "－10℃"], "optsVi": ["6℃", "0℃", "−2℃", "−10℃"], "optsEn": ["6°C", "0°C", "−2°C", "−10°C"], "ans": 2, "expJa": "地域冷水は6～7℃程度なので、冷房に必要な低温を得るには、冷水コイルを通った空気を冷凍装置で－2℃まで下げる必要がある。暖房は50～60℃の温水だけで足りる。", "expVi": "Nước lạnh khu vực chỉ khoảng 6–7℃, nên để có khí đủ lạnh phải dùng thiết bị làm lạnh hạ không khí sau cuộn nước lạnh xuống −2℃. Còn sưởi thì nước nóng 50–60℃ là đủ.", "expEn": "District chilled water is only about 6-7°C, so a refrigeration unit must cool the air from the coil down to -2°C; for heating, 50-60°C hot water alone is enough."},
  {"id": "S2G21", "topic": "s2_gse", "level": 2, "src": "SSW2テキスト 7-4-3 (p.72)", "qJa": "除雪車（大型クレーンの先にゴンドラを備えたもの）について、テキストの記述として正しいものはどれか？", "qVi": "Về xe dọn tuyết (có giỏ nâng ở đầu cần cẩu lớn), nội dung nào đúng theo giáo trình?", "qEn": "According to the textbook, which statement about the snow removal vehicle (a large crane with a gondola) is correct?", "optsJa": ["約60℃の除雪氷液を噴射し、1台・約30分で機体の雪を取り除ける", "約80℃の温水を噴射し、2台・約10分で機体の雪を取り除ける", "ノズルを機体から約5m離し、高圧空気だけを使って雪を吹き飛ばす", "ゴンドラは屋根のない作業台で、暖房設備は備えていない"], "optsVi": ["Phun dung dịch phá băng khoảng 60℃, 1 xe mất khoảng 30 phút để dọn tuyết", "Phun nước nóng ~80℃, 2 xe dọn tuyết trong khoảng 10 phút", "Giữ vòi cách thân khoảng 5m và chỉ dùng khí áp cao để thổi tuyết", "Giỏ nâng là sàn làm việc không mái, không có thiết bị sưởi"], "optsEn": ["Sprays about 60°C fluid; one unit clears it in about 30 minutes", "Sprays about 80°C water; two units clear it in about 10 minutes", "It keeps the nozzle about 5 m away and blows snow off with air only", "The gondola is an open work platform with no heating at all"], "ans": 1, "expJa": "ゴンドラに乗ったままブームを操作し、ノズルを機体の約1mまで近づけて80℃の温水を噴射することで、2台で約10分で雪を除去できる。ゴンドラはキャビン式でヒーターも入る。", "expVi": "Người vận hành đứng trong giỏ điều khiển cần, đưa vòi đến cách thân khoảng 1m và phun nước nóng 80℃, 2 xe dọn tuyết trong khoảng 10 phút. Giỏ là dạng cabin có lắp máy sưởi.", "expEn": "Operating the boom from the gondola, the nozzle is brought to about 1 m from the aircraft and 80°C water is sprayed, so two units clear the snow in about 10 minutes. The gondola is an enclosed cabin with a heater."},
  {"id": "S2G22", "topic": "s2_gse", "level": 2, "src": "SSW2テキスト 7-5-1 b (p.76)", "qJa": "ゴミ袋に詰めたゴミを後部荷台から積み込み、床のオート・コンベアで荷台の中へ送り込むゴミ運搬車両はどれか？", "qVi": "Xe chở rác nào cho túi rác vào từ thùng phía sau và dùng băng tải tự động trên sàn để đẩy vào trong thùng?", "qEn": "Which trash vehicle takes bagged trash in at the rear and moves it inside with a floor auto-conveyor?", "optsJa": ["ダスト・ボックス", "トラッシュ・カー", "キャビン・サービス・カー", "ラバトリー・カー"], "optsVi": ["Dust box (ダスト・ボックス)", "Trash car (トラッシュ・カー)", "Cabin service car (キャビン・サービス・カー)", "Lavatory car (ラバトリー・カー)"], "optsEn": ["Dust box", "Trash car", "Cabin service car", "Lavatory car"], "ans": 0, "expJa": "ダスト・ボックスは後部から積んだゴミ袋をオート・コンベアで奥へ送り、排出時はコンベアを逆転させて残らず出す。トラッシュ・カーは荷台上部のハッチを開けて上からゴミを入れるタイプである。", "expVi": "Dust box đưa túi rác từ phía sau vào trong bằng băng tải tự động, khi xả thì chạy ngược băng tải để đổ hết. Còn trash car là loại mở cửa sập phía trên thùng để bỏ rác từ trên xuống.", "expEn": "The dust box moves rear-loaded trash bags inward on an auto-conveyor and reverses it to empty everything; the trash car instead has a top hatch through which trash is thrown in."},
  {"id": "S2S01", "topic": "s2_safety", "level": 2, "src": "SSW2テキスト 8-1 b (p.77)", "qJa": "安全推進運動において、三位一体として取り組むとされる3つの基本要綱はどれか。", "qVi": "Trong phong trào thúc đẩy an toàn (安全推進運動), 3 trụ cột cơ bản được kết hợp làm một (三位一体) là gì?", "qEn": "In the safety promotion campaign, which three basic pillars are treated as one integrated whole?", "optsJa": ["教育・訓練・監査", "教育・管理・技術", "管理・点検・報告", "技術・設備・予算"], "optsVi": ["Giáo dục, huấn luyện, kiểm toán", "Giáo dục, quản lý, kỹ thuật", "Quản lý, kiểm tra, báo cáo", "Kỹ thuật, thiết bị, ngân sách"], "optsEn": ["Education, training, auditing", "Education, management, technology", "Management, inspection, reporting", "Technology, equipment, budget"], "ans": 1, "expJa": "テキストでは、安全教育・安全管理・安全技術の3つを一体のものとして安全の問題に取り組むとしている。", "expVi": "Giáo trình nêu rằng vấn đề an toàn được giải quyết bằng cách kết hợp 3 trụ cột: giáo dục an toàn, quản lý an toàn và kỹ thuật an toàn.", "expEn": "The textbook says safety is tackled by combining safety education, safety management and safety technology as one."},
  {"id": "S2S02", "topic": "s2_safety", "level": 2, "src": "SSW2テキスト 8-1 e (p.79)", "qJa": "事故を未然に防ぐ仕組みのうち、「フール・プルーフ（Fool Proof）」の説明として正しいものはどれか。", "qVi": "Trong các cơ chế phòng ngừa tai nạn, mô tả nào đúng về \"Fool Proof\" (フール・プルーフ)?", "qEn": "Among the mechanisms that prevent accidents, which correctly describes \"fool proof\"?", "optsJa": ["故障しても安全が保たれる二重三重のバックアップ", "誤操作を防ぐ自動操縦装置などの安全装置", "個人の失敗をクルー全体の失敗にしないチームワーク", "誤操作をしても作動せず、ミスができない仕組み"], "optsVi": ["Hệ thống dự phòng nhiều lớp, dù hỏng vẫn giữ được an toàn", "Thiết bị an toàn như lái tự động để ngăn thao tác sai", "Làm việc nhóm để lỗi cá nhân không thành lỗi của cả tổ bay", "Cơ chế mà dù thao tác sai cũng không vận hành, không thể mắc lỗi"], "optsEn": ["A double or triple backup that stays safe even when something fails", "Safety devices such as autopilot that prevent operating errors", "Teamwork so one pilot's error does not become the whole crew's error", "A design that will not operate on a wrong input, so mistakes cannot be made"], "ans": 3, "expJa": "フール・プルーフは、誤った操作をしても作動しない、つまり人が間違えようとしても間違えられない仕組みである。二重三重のバックアップはフェール・セーフ、チームワークはCRMの説明である。", "expVi": "Fool Proof là hệ thống mà dù thao tác nhầm cũng không hoạt động, tức là muốn sai cũng không sai được. Dự phòng nhiều lớp là Fail Safe, còn làm việc nhóm là CRM.", "expEn": "Fool proof means the system does not work when operated wrongly, so an error cannot be made. Multiple backups describe fail safe, and teamwork describes CRM."},
  {"id": "S2S03", "topic": "s2_safety", "level": 2, "src": "SSW2テキスト 8-1 e (pp.79-80)", "qJa": "「事故、災害要因の4つのM」に含まれないものはどれか。", "qVi": "Yếu tố nào KHÔNG thuộc \"4M - các yếu tố gây tai nạn, thảm họa\" (事故、災害要因の4つのM)?", "qEn": "Which of the following is NOT one of the \"4 Ms\" of accident and disaster factors?", "optsJa": ["Method（方法）", "Man（人間）", "Machine（物、機械）", "Media（環境、媒体）"], "optsVi": ["Method (phương pháp)", "Man (con người)", "Machine (máy móc)", "Media (môi trường)"], "optsEn": ["Method", "Man (people)", "Machine (things, equipment)", "Media (environment)"], "ans": 0, "expJa": "事故の要因は人・物・環境（媒体）・管理の4つで、Man、Machine、Media、Managementの頭文字から4Mと呼ばれる。Methodは含まれない。", "expVi": "4 yếu tố gây tai nạn là con người, vật/máy móc, môi trường và quản lý: Man, Machine, Media, Management. Method không nằm trong 4M.", "expEn": "The four factors are people, machines, environment and management: Man, Machine, Media and Management. Method is not one of them."},
  {"id": "S2S04", "topic": "s2_safety", "level": 2, "src": "SSW2テキスト 8-1 e (p.80)", "qJa": "テキストでは、事故要因の何％以上が人的要因によるものと言われているか。", "qVi": "Theo giáo trình, người ta nói rằng bao nhiêu % trở lên các nguyên nhân tai nạn là do yếu tố con người?", "qEn": "According to the textbook, at least what percentage of accident factors is said to be human factors?", "optsJa": ["50％", "30％", "70％", "90％"], "optsVi": ["50%", "30%", "70%", "90%"], "optsEn": ["50%", "30%", "70%", "90%"], "ans": 2, "expJa": "人的要因は事故要因の70％以上を占めるとされ、管理の要因も人の問題に帰するため、人が関与しない事故は極めてわずかである。", "expVi": "Người ta nói hơn 70% nguyên nhân tai nạn là do con người; yếu tố quản lý cũng quy về con người, nên tai nạn không có con người liên quan là rất ít.", "expEn": "Human factors are said to cause over 70% of accidents, and management factors also come back to people, so accidents with no human involvement are very rare."},
  {"id": "S2S05", "topic": "s2_safety", "level": 2, "src": "SSW2テキスト 8-1 f (p.81)", "qJa": "ハインリッヒの法則で示される、マイナー・エラー：インシデント：アクシデントの数の比はどれか。", "qVi": "Theo định luật Heinrich (ハインリッヒの法則), tỷ lệ lỗi nhỏ : sự cố suýt xảy ra (インシデント) : tai nạn (アクシデント) là bao nhiêu?", "qEn": "Under Heinrich's law, what is the ratio of minor errors to incidents to accidents?", "optsJa": ["100：10：1", "300：30：3", "300：29：1", "1000：100：1"], "optsVi": ["100 : 10 : 1", "300 : 30 : 3", "300 : 29 : 1", "1000 : 100 : 1"], "optsEn": ["100 : 10 : 1", "300 : 30 : 3", "300 : 29 : 1", "1000 : 100 : 1"], "ans": 2, "expJa": "ハインリッヒの法則では3者の比はほぼ300：29：1とされ、件数が圧倒的に多い小さなエラーやヒヤリハットにこそ対策が必要だとしている。", "expVi": "Định luật Heinrich cho tỷ lệ khoảng 300 : 29 : 1, vì vậy cần tập trung đối sách vào lỗi nhỏ và sự cố suýt xảy ra vốn chiếm số lượng lớn.", "expEn": "Heinrich's law gives a ratio of about 300:29:1, so countermeasures should focus on the far more numerous minor errors and incidents."},
  {"id": "S2S06", "topic": "s2_safety", "level": 2, "src": "SSW2テキスト 8-1 g (p.81)", "qJa": "ICAOの「事故防止マニュアル」に示される「事象のチェーン」分析で、重要とされる観点はどれか。", "qVi": "Khi phân tích \"chuỗi sự kiện\" (事象のチェーン) theo Sổ tay phòng ngừa tai nạn của ICAO, quan điểm nào được coi là quan trọng?", "qEn": "In \"chain of events\" analysis from ICAO's Accident Prevention Manual, which viewpoint is considered important?", "optsJa": ["誰が事故を防ぐことができたのか", "誰に事故の責任があるのか", "事故の主原因を一つに絞ること", "現場の作業者に何が足りなかったか"], "optsVi": ["Ai đã có thể ngăn được tai nạn", "Ai phải chịu trách nhiệm về tai nạn", "Thu hẹp về một nguyên nhân chính duy nhất", "Người làm việc tại hiện trường thiếu điều gì"], "optsEn": ["Who could have prevented the accident", "Who is to blame for the accident", "Narrowing it down to one main cause", "What the frontline worker was lacking"], "ans": 0, "expJa": "事象のチェーン分析は上流へさかのぼるため、責任追及型の考えでは機能しない。「誰が防げたか」という視点が重要で、主原因から多重原因の考え方への転換を促す。", "expVi": "Phân tích chuỗi sự kiện truy ngược lên phía trên nên cách nghĩ truy cứu trách nhiệm sẽ không hiệu quả. Quan trọng là \"ai có thể ngăn được\", và nó thúc đẩy chuyển từ \"một nguyên nhân chính\" sang \"nhiều nguyên nhân\".", "expEn": "Because the analysis traces causes upstream, a blame-seeking approach does not work. The key question is who could have prevented it, and it moves thinking from a single main cause to multiple causes."},
  {"id": "S2S07", "topic": "s2_safety", "level": 2, "src": "SSW2テキスト 8-1 g (p.82)", "qJa": "拡大SHELLモデルで中心に置かれる「L」は何を表すか。", "qVi": "Trong mô hình SHELL mở rộng (拡大SHELLモデル), chữ \"L\" đặt ở trung tâm biểu thị điều gì?", "qEn": "In the expanded SHELL model, what does the central \"L\" stand for?", "optsJa": ["ロジスティクス（物流）", "ライセンス（資格）", "レイアウト（配置）", "ライブウェア（人間）"], "optsVi": ["Logistics (hậu cần)", "License (chứng chỉ)", "Layout (bố trí)", "Liveware (con người)"], "optsEn": ["Logistics", "License (qualification)", "Layout", "Liveware (people)"], "ans": 3, "expJa": "SHELLモデルでは、人間（L：ライブウェア）と、ハードウエア・ソフトウエア・環境・他の人間との接点に不具合があるとエラーが起こりやすいと考える。", "expVi": "Mô hình SHELL cho rằng lỗi dễ xảy ra khi có trục trặc ở điểm tiếp xúc giữa con người (L: Liveware) với phần cứng, phần mềm, môi trường và những người khác.", "expEn": "The SHELL model holds that errors are likely when there is a mismatch between the human (L, liveware) and hardware, software, environment or other people."},
  {"id": "S2S08", "topic": "s2_safety", "level": 2, "src": "SSW2テキスト 8-1 g (p.82)", "qJa": "「ヒヤリ・ハット・レポート」法が有効に機能するために重要とされるものはどれか。", "qVi": "Để phương pháp \"báo cáo suýt xảy ra sự cố\" (ヒヤリ・ハット・レポート) hoạt động hiệu quả, điều gì được coi là quan trọng?", "qEn": "What is considered important for the \"near-miss report\" method to work effectively?", "optsJa": ["報告者の氏名公表と、エラーへの処罰の明確化", "十分なフィードバックと、エラーを隠さなくてよい風土", "報告件数のノルマ化と、件数による部署の評価", "事故発生時に限った報告と、管理者の一括処理"], "optsVi": ["Công khai tên người báo cáo và quy định rõ hình phạt", "Phản hồi đầy đủ và môi trường không cần che giấu lỗi", "Đặt chỉ tiêu số báo cáo và đánh giá bộ phận theo số đó", "Chỉ báo cáo khi có tai nạn và để quản lý xử lý một lần"], "optsEn": ["Naming reporters and making penalties for errors clear", "Good feedback and a culture with no need to hide errors", "Report quotas and rating sections by report counts", "Reporting only after accidents, handled by managers"], "ans": 1, "expJa": "エラー情報の共有や組織的対応といった十分なフィードバックと、エラーを隠さずに済む開かれた安全風土が重要とされる。処罰の恐れはむしろ報告を妨げる。", "expVi": "Cần phản hồi đầy đủ như chia sẻ thông tin lỗi, xử lý có tổ chức, cùng một văn hóa an toàn cởi mở không phải giấu lỗi. Nỗi sợ bị phạt lại cản trở việc báo cáo.", "expEn": "Sufficient feedback, such as sharing error information and responding as an organization, plus an open safety culture where errors need not be hidden, are key. Fear of punishment discourages reporting."},
  {"id": "S2S09", "topic": "s2_safety", "level": 2, "src": "SSW2テキスト 8-1 h 表8-2 (p.83)", "qJa": "安全阻害要因の是正で、事故要因の4Mに適用する「対策の4E」に含まれるものはどれか。", "qVi": "Khi khắc phục yếu tố cản trở an toàn, mục nào thuộc \"4E đối sách\" (対策の4E) áp dụng cho 4M?", "qEn": "When correcting safety hazards, which item belongs to the \"4 Es\" of countermeasures applied to the 4 Ms?", "optsJa": ["Example", "Exercise", "Economy", "Equipment"], "optsVi": ["Example", "Exercise", "Economy", "Equipment"], "optsEn": ["Example", "Exercise", "Economy", "Equipment"], "ans": 0, "expJa": "表8-2では対策の4EとしてEngineering、Education、Enforcement、Exampleが示されている。", "expVi": "Bảng 8-2 nêu 4E đối sách gồm Engineering, Education, Enforcement và Example.", "expEn": "Table 8-2 lists the 4 Es of countermeasures as Engineering, Education, Enforcement and Example."},
  {"id": "S2S10", "topic": "s2_safety", "level": 2, "src": "SSW2テキスト 8-2 a (p.85)", "qJa": "制限区域内で航空機の運航が最優先とされる理由として、誤っているものはどれか。", "qVi": "Lý do tàu bay được ưu tiên cao nhất trong khu vực hạn chế (制限区域), điều nào KHÔNG đúng?", "qEn": "Which is NOT a correct reason why aircraft operations have top priority in the restricted area?", "optsJa": ["構造上、動きが機敏でないから", "操縦席からの視界が極めて悪いから", "管制塔と常に交信しているから", "燃料など可燃物を多量に積んでいるから"], "optsVi": ["Vì cấu tạo nên di chuyển không linh hoạt", "Vì tầm nhìn từ buồng lái rất kém", "Vì luôn liên lạc với đài kiểm soát", "Vì chở nhiều chất dễ cháy như nhiên liệu"], "optsEn": ["Because its structure makes it slow to maneuver", "Because visibility from the cockpit is very poor", "Because it is always in contact with the tower", "Because it carries a lot of fuel and flammables"], "ans": 2, "expJa": "理由として挙げられているのは、動きが機敏でない、視界が極めて悪い、多量の可燃性物質を搭載している、高価である、などである。管制塔との交信は理由に含まれない。", "expVi": "Các lý do được nêu là: di chuyển không linh hoạt, tầm nhìn rất kém, chở nhiều chất dễ cháy, và giá trị cao. Việc liên lạc với đài kiểm soát không phải là lý do.", "expEn": "The reasons given are that aircraft are not agile, have very poor visibility, carry large amounts of flammable material and are expensive. Contact with the tower is not listed."},
  {"id": "S2S11", "topic": "s2_safety", "level": 2, "src": "SSW2テキスト 8-2 f (p.88)", "qJa": "航空機の前方下部貨物室ドアなどへ車両を誘導する場合、プロペラまたはジェット・エンジン口と車両の間隔をどれだけあけるか。", "qVi": "Khi dẫn xe đến cửa khoang hàng dưới phía trước của tàu bay, phải giữ khoảng cách giữa xe và cánh quạt hoặc miệng động cơ phản lực bao nhiêu?", "qEn": "When guiding a vehicle to a forward lower cargo door, what gap must be kept between the vehicle and the propeller or jet engine inlet?", "optsJa": ["50cm以上", "1m以上", "3m以上", "5m以上"], "optsVi": ["Từ 50 cm trở lên", "Từ 1 m trở lên", "Từ 3 m trở lên", "Từ 5 m trở lên"], "optsEn": ["At least 50 cm", "At least 1 m", "At least 3 m", "At least 5 m"], "ans": 1, "expJa": "誘導者の義務として、前方下部貨物室ドアなどへ誘導する際は、プロペラやエンジン口と車両を1m以上離した位置へ誘導するとされている。", "expVi": "Theo nghĩa vụ của người dẫn đường (誘導者), khi dẫn xe đến cửa khoang hàng dưới phía trước, phải dừng xe ở vị trí cách cánh quạt hay miệng động cơ từ 1 m trở lên.", "expEn": "One of the guide's duties is to position the vehicle at least 1 m away from the propeller or engine inlet when guiding it to a forward lower cargo door."},
  {"id": "S2S12", "topic": "s2_safety", "level": 2, "src": "SSW2テキスト 8-2 g (p.89)", "qJa": "フォークリフトの危険防止として、テキストに示されている内容はどれか。", "qVi": "Về phòng ngừa nguy hiểm với xe nâng (フォークリフト), nội dung nào được nêu trong giáo trình?", "qEn": "Which of the following is stated in the textbook for preventing forklift hazards?", "optsJa": ["フォークが動いている3m以内に近づかない", "荷役中は前進が基本のため前方に近づかない", "荷の下に入る場合は短時間で作業を終える", "フォークが動いている1.5m以内に近づかない"], "optsVi": ["Không lại gần trong phạm vi 3 m khi càng nâng đang chuyển động", "Khi bốc dỡ xe chủ yếu chạy tiến nên không lại gần phía trước", "Nếu phải chui xuống dưới hàng thì làm thật nhanh", "Không lại gần trong phạm vi 1,5 m khi càng nâng đang chuyển động"], "optsEn": ["Stay out of 3 m while the forks are moving", "Stay away from the front, as it mainly moves forward", "Finish quickly if you must go under the load", "Stay out of 1.5 m while the forks are moving"], "ans": 3, "expJa": "フォークが動いているときは1.5m以内に近づかないこと、また荷役中は後進が基本なので後方に注意することが示されている。フォークや荷の下に入ることは禁止である。", "expVi": "Không được lại gần trong vòng 1,5 m khi càng nâng chuyển động; khi bốc dỡ xe chủ yếu chạy lùi nên phải chú ý phía sau. Cấm chui xuống dưới càng hoặc hàng.", "expEn": "Do not come within 1.5 m of moving forks; during cargo handling the forklift mainly reverses, so watch the rear. Going under the forks or load is prohibited."},
  {"id": "S2S13", "topic": "s2_safety", "level": 2, "src": "SSW2テキスト 8-3 c (p.92)", "qJa": "航空機作業に係る高所作業車のうち、作業床の高さが2m以上10m未満の車両を操作するための要件はどれか。", "qVi": "Đối với xe làm việc trên cao (高所作業車) có sàn thao tác cao từ 2 m đến dưới 10 m, điều kiện để vận hành là gì?", "qEn": "For an aerial work vehicle whose platform is 2 m or more but under 10 m high, what is required to operate it?", "optsJa": ["技能講習も特別教育も必要ない", "技能講習修了証の交付を受ける", "事業者が行う特別教育を受講する", "航空局の講習を受け試験に合格する"], "optsVi": ["Không cần khóa kỹ năng hay giáo dục đặc biệt", "Được cấp giấy hoàn thành khóa học kỹ năng", "Học khóa giáo dục đặc biệt do doanh nghiệp tổ chức", "Học khóa của Cục Hàng không và đỗ kỳ thi"], "optsEn": ["Neither skills course nor special training is needed", "Receive a certificate for the skills course", "Take the special training given by the employer", "Pass the Civil Aviation Bureau course and exam"], "ans": 2, "expJa": "平成2年10月の変更により、作業床が2m以上10m未満の車両は事業者が行う特別教育を受ければ操作できる。10m以上は技能講習修了証が必要で、2m未満は技能講習不要とされる。", "expVi": "Theo thay đổi tháng 10/1990 (平成2年), xe có sàn từ 2 m đến dưới 10 m có thể vận hành sau khi học giáo dục đặc biệt do doanh nghiệp tổ chức. Từ 10 m trở lên cần giấy hoàn thành khóa kỹ năng.", "expEn": "Since the October 1990 change, vehicles with a 2 m to under 10 m platform may be operated after special training provided by the employer. Platforms of 10 m or more require a skills course certificate."},
  {"id": "S2Q01", "topic": "s2_quality", "level": 2, "src": "SSW2テキスト 9-1-1 (p.94)", "qJa": "JIS（日本工業規格）では、品質管理をどのように説明しているか。", "qVi": "Tiêu chuẩn JIS (日本工業規格) giải thích quản lý chất lượng (品質管理) như thế nào?", "qEn": "How does JIS (Japanese Industrial Standards) describe quality control?", "optsJa": ["売り手の基準に合った品物を選別する検査の仕組み", "費用に関係なく最高品質の品物を作り出す体系", "不良品を出荷前にすべて取り除くための手順", "買い手の要求に合った品質の品物を作り出す手段と体系"], "optsVi": ["Cơ chế kiểm tra để chọn lọc sản phẩm theo tiêu chuẩn của người bán", "Hệ thống tạo ra sản phẩm chất lượng cao nhất bất kể chi phí", "Quy trình loại bỏ toàn bộ hàng lỗi trước khi xuất hàng", "Phương tiện, hệ thống tạo ra hàng đúng chất lượng người mua cần"], "optsEn": ["An inspection system that sorts goods by the seller's standards", "A system for making top-quality goods regardless of cost", "A procedure for removing every defect before shipment", "The means and system for producing goods whose quality meets buyers' needs"], "ans": 3, "expJa": "JISは品質管理を、買い手が求める品質の品物を生み出すための手段・体系としている。目的は、顧客の求める品質を満たす商品・サービスを妥当な価格で時機よく届けることである。", "expVi": "JIS định nghĩa quản lý chất lượng là phương tiện, hệ thống tạo ra sản phẩm đúng chất lượng người mua cần. Mục đích là cung cấp hàng hóa, dịch vụ đạt chất lượng khách yêu cầu, với giá hợp lý và đúng lúc.", "expEn": "JIS describes it as the means and system for making goods of the quality buyers want. Its aim is to deliver goods and services that meet customer quality needs at a fair price and at the right time."},
  {"id": "S2Q02", "topic": "s2_quality", "level": 2, "src": "SSW2テキスト 9-1-2 (p.94)", "qJa": "航空輸送の品質として、一般に言われている3つの要素はどれか。", "qVi": "Chất lượng của vận tải hàng không thường được nói là gồm 3 yếu tố nào?", "qEn": "Which three elements are generally said to make up the quality of air transport?", "optsJa": ["安全性・定時性・快適性", "安全性・経済性・利便性", "定時性・快適性・低価格", "安全性・迅速性・正確性"], "optsVi": ["An toàn, đúng giờ, thoải mái", "An toàn, kinh tế, tiện lợi", "Đúng giờ, thoải mái, giá rẻ", "An toàn, nhanh chóng, chính xác"], "optsEn": ["Safety, punctuality, comfort", "Safety, economy, convenience", "Punctuality, comfort, low price", "Safety, speed, accuracy"], "ans": 0, "expJa": "航空輸送の品質は一般に安全性・定時性・快適性とされ、言い換えれば旅客に快適に旅をしてもらい、確実に目的地へ届けることである。", "expVi": "Chất lượng vận tải hàng không thường gồm an toàn (安全性), đúng giờ (定時性) và thoải mái (快適性), tức là cho hành khách đi lại dễ chịu và đưa họ đến nơi một cách chắc chắn.", "expEn": "Air transport quality is generally safety, punctuality and comfort: letting passengers travel comfortably and getting them reliably to their destination."},
  {"id": "S2Q03", "topic": "s2_quality", "level": 2, "src": "SSW2テキスト 9-1-3 (p.94)", "qJa": "テキストでは、「サービスの品質」とは何であると言われているか。", "qVi": "Theo giáo trình, \"chất lượng dịch vụ\" (サービスの品質) được nói là gì?", "qEn": "According to the textbook, what is \"service quality\" said to be?", "optsJa": ["提供者が定めた基準の達成", "顧客の期待に対する満足", "価格に見合った設備の充実", "従業員の作業スピードの速さ"], "optsVi": ["Việc đạt tiêu chuẩn do bên cung cấp đặt ra", "Sự hài lòng so với kỳ vọng của khách hàng", "Trang thiết bị đầy đủ tương xứng với giá", "Tốc độ làm việc nhanh của nhân viên"], "optsEn": ["Meeting standards set by the provider", "Satisfaction relative to customers' expectations", "Facilities that match the price paid", "How fast employees do their work"], "ans": 1, "expJa": "サービスの品質は顧客の期待に対する満足だとされる。また一般に品質は要求される条件に適合することであり、単に良ければ良いというものではない。", "expVi": "Chất lượng dịch vụ là sự hài lòng so với kỳ vọng của khách. Chất lượng là sự phù hợp với yêu cầu, không đơn giản là càng tốt càng hay.", "expEn": "Service quality is satisfaction against customer expectations. Quality means conforming to requirements, not simply being as good as possible."},
  {"id": "S2Q04", "topic": "s2_quality", "level": 2, "src": "SSW2テキスト 9-1-3 (p.95)", "qJa": "企業がどのような客層を狙うかを決め、それによってサービス品質を決めていくことを何というか。", "qVi": "Việc doanh nghiệp quyết định nhắm đến tầng lớp khách hàng nào, từ đó quyết định chất lượng dịch vụ, được gọi là gì?", "qEn": "What is it called when a company decides which customer segment to target and sets its service quality accordingly?", "optsJa": ["サービスの標準化", "サービスの効率化", "サービスの戦略", "サービスの差別化"], "optsVi": ["Tiêu chuẩn hóa dịch vụ", "Hiệu quả hóa dịch vụ", "Chiến lược dịch vụ (サービスの戦略)", "Khác biệt hóa dịch vụ"], "optsEn": ["Service standardization", "Service streamlining", "Service strategy", "Service differentiation"], "ans": 2, "expJa": "ターゲットとする客層を定めることがサービスの戦略であり、例えばファースト・ビジネス・エコノミーとクラスを分けることでサービス内容が決まる。", "expVi": "Việc xác định tầng lớp khách hàng mục tiêu gọi là \"chiến lược dịch vụ\"; ví dụ chia hạng First, Business, Economy sẽ quyết định nội dung dịch vụ.", "expEn": "Deciding the target customers is called service strategy; for example, dividing into First, Business and Economy classes determines the service content."},
  {"id": "S2Q05", "topic": "s2_quality", "level": 2, "src": "SSW2テキスト 9-1-4 (p.95)", "qJa": "「人的サービス」の説明として正しいものはどれか。", "qVi": "Mô tả nào đúng về \"dịch vụ con người\" (人的サービス)?", "qEn": "Which correctly describes \"human service\"?", "optsJa": ["設備・飲食物・居住性などの物の質", "受け手が提供者について感じる良し悪しの感覚", "仕事の進め方や手順、人のやりくり", "情報の質と量、価格およびタイミング"], "optsVi": ["Chất lượng vật chất như thiết bị, đồ ăn uống, độ tiện nghi", "Cảm nhận tốt hay xấu của người nhận về người phục vụ", "Cách tiến hành công việc, quy trình, bố trí nhân sự", "Chất lượng, số lượng thông tin, giá cả và thời điểm"], "optsEn": ["The quality of facilities, food and drink, and comfort", "The good or bad feeling the receiver has about the provider", "How work is done, procedures and staff allocation", "Quality and amount of information, price and timing"], "ans": 1, "expJa": "人的サービスは、サービスの受け手が提供者に対して抱く「フィーリング」（良い・悪い）である。設備や手順、情報、価格などは物的サービスに含まれる。", "expVi": "Dịch vụ con người là \"cảm nhận\" (tốt/xấu) mà người nhận có về người cung cấp. Thiết bị, quy trình, thông tin, giá cả… thuộc dịch vụ vật chất (物的サービス).", "expEn": "Human service is the feeling, good or bad, the receiver has about the provider. Facilities, procedures, information and price belong to physical service."},
  {"id": "S2Q06", "topic": "s2_quality", "level": 2, "src": "SSW2テキスト 9-1-5 (p.95)", "qJa": "テキストで「旅客へのサービスの原点」とされているものはどれか。", "qVi": "Theo giáo trình, điều gì được coi là \"điểm khởi đầu của dịch vụ cho hành khách\"?", "qEn": "What does the textbook call the starting point of service to passengers?", "optsJa": ["物的サービスの質の向上", "上級クラス旅客への特別対応", "苦情に対する迅速な対応", "社内サービス（仲間へのサービス）"], "optsVi": ["Nâng cao dịch vụ vật chất", "Phục vụ đặc biệt khách hạng cao", "Xử lý khiếu nại nhanh chóng", "Dịch vụ nội bộ cho đồng nghiệp"], "optsEn": ["Improving physical service", "Premium passenger care", "Quick handling of complaints", "Internal service to colleagues"], "ans": 3, "expJa": "同僚・仲間に対する社内のサービスこそが旅客サービスの原点とされる。部門間や上司と部下が互いに支え合うことで培われたノウハウと精神が、旅客への良いサービスの出発点になる。", "expVi": "Dịch vụ nội bộ (phục vụ đồng nghiệp) là gốc của dịch vụ cho hành khách. Khi các bộ phận, cấp trên và cấp dưới hỗ trợ nhau, bí quyết và tinh thần đó trở thành điểm xuất phát cho dịch vụ tốt với khách.", "expEn": "Internal service, or service to colleagues, is the origin of passenger service. Mutual support between departments and between bosses and staff builds the know-how and spirit for good passenger service."},
  {"id": "S2Q07", "topic": "s2_quality", "level": 2, "src": "SSW2テキスト 9-2 (pp.95-96)", "qJa": "グランドハンドリング会社が、人身災害や航空機・車両機材の損傷も基本的に同列に対処すべきとされる理由はどれか。", "qVi": "Vì sao công ty phục vụ mặt đất (グランドハンドリング会社) về cơ bản phải xử lý ngang nhau cả tai nạn người lẫn hư hỏng tàu bay, xe, thiết bị?", "qEn": "Why should a ground handling company basically deal with injuries and damage to aircraft or equipment on the same level?", "optsJa": ["「作業」そのものを「商品」として売っているから", "書類手続き上すべて同じ様式で処理するから", "どの不具合も損害額がほぼ同じになるから", "法令で同一の報告書提出が求められるから"], "optsVi": ["Vì bán chính \"công việc\" như một \"sản phẩm\"", "Vì về thủ tục giấy tờ đều xử lý cùng mẫu", "Vì mọi sự cố đều có mức thiệt hại gần như nhau", "Vì luật yêu cầu nộp cùng một loại báo cáo"], "optsEn": ["Because it sells the work itself as its product", "Because all are handled on the same paperwork form", "Because every problem costs about the same", "Because the law requires the same report for all"], "ans": 0, "expJa": "GH会社は作業自体を商品として販売しているため、書類上は扱いが異なる場合があっても、不具合は基本的に同列に扱う。作業の安全がそのまま作業の品質だとされる。", "expVi": "Công ty phục vụ mặt đất bán chính công việc như sản phẩm, nên dù giấy tờ có thể xử lý khác nhau, các sự cố về cơ bản được đối xử như nhau. An toàn công việc chính là chất lượng công việc.", "expEn": "Because the company sells the work itself as its product, problems are basically treated alike even if paperwork differs. Work safety is described as work quality itself."},
  {"id": "S2Q08", "topic": "s2_quality", "level": 2, "src": "SSW2テキスト 9-3 (p.96)", "qJa": "品質管理に意味があるために、通常成り立っているべき関係はどれか。", "qVi": "Để quản lý chất lượng có ý nghĩa, thông thường phải có quan hệ nào giữa các chi phí?", "qEn": "For quality control to make sense, which cost relationship should normally hold?", "optsJa": ["欠陥コスト＜欠陥防止コスト", "欠陥コスト＝欠陥防止コスト", "欠陥コスト＞欠陥防止コスト", "欠陥防止コスト＝0"], "optsVi": ["Chi phí do lỗi < chi phí phòng ngừa lỗi", "Chi phí do lỗi = chi phí phòng ngừa lỗi", "Chi phí do lỗi > chi phí phòng ngừa lỗi", "Chi phí phòng ngừa lỗi = 0"], "optsEn": ["Cost of defects < cost of preventing them", "Cost of defects = cost of preventing them", "Cost of defects > cost of preventing them", "Cost of preventing defects = 0"], "ans": 2, "expJa": "通常は欠陥コストの方が欠陥防止コストより大きく、欠陥より少ない費用で欠陥を防げる。そうでなければ品質管理を行う意味がないとされる。", "expVi": "Thông thường chi phí do lỗi lớn hơn chi phí phòng ngừa, tức là có thể ngăn lỗi với chi phí thấp hơn. Nếu không như vậy thì quản lý chất lượng không có ý nghĩa.", "expEn": "Normally the cost of defects exceeds the cost of preventing them, so defects can be prevented more cheaply. Otherwise quality control would be pointless."},
  {"id": "S2Q09", "topic": "s2_quality", "level": 2, "src": "SSW2テキスト 9-4 図9-1 (p.97)", "qJa": "ヒューマン・エラーの要因となる人間の弱点として、テキストに示されている反応時間はどの程度か。", "qVi": "Trong các điểm yếu của con người gây ra lỗi (ヒューマン・エラー), giáo trình nêu thời gian phản ứng khoảng bao nhiêu?", "qEn": "Among human weaknesses that cause human error, about how long is the reaction time given in the textbook?", "optsJa": ["0.2秒程度", "0.02秒程度", "1秒程度", "2秒程度"], "optsVi": ["Khoảng 0,2 giây", "Khoảng 0,02 giây", "Khoảng 1 giây", "Khoảng 2 giây"], "optsEn": ["About 0.2 seconds", "About 0.02 seconds", "About 1 second", "About 2 seconds"], "ans": 0, "expJa": "図9-1では人間の弱点の一つとして速度に限界があることを挙げ、反応時間は0.2秒程度あるとしている。人は誰でも間違えるとの前提で、弱点をカバーする策を組み込む必要がある。", "expVi": "Hình 9-1 nêu một điểm yếu là tốc độ có giới hạn, thời gian phản ứng khoảng 0,2 giây. Cần xây dựng biện pháp bù đắp điểm yếu với tiền đề ai cũng có thể sai.", "expEn": "Figure 9-1 lists limited speed as a weakness, with a reaction time of about 0.2 seconds. Measures that cover human weaknesses must be built in, on the basis that anyone can make mistakes."},
  {"id": "S2A01", "topic": "s2_rules", "level": 2, "src": "SSW2テキスト 10-3-1 3. (p.118)", "qJa": "東京国際空港制限区域安全管理規程の立ち入り区域の区分で、「第三種地区」に該当する範囲はどれか。", "qVi": "Theo phân loại khu vực được vào trong Quy chế quản lý an toàn khu vực hạn chế sân bay Haneda, \"khu loại 3\" (第三種地区) gồm phạm vi nào?", "qEn": "Under the Haneda restricted area safety rules, which area makes up a \"Class 3 zone\"?", "optsJa": ["滑走路を含む制限区域全域", "エプロン及び車両通路", "エプロン・場周道路・車両通路", "エプロン及び場周道路"], "optsVi": ["Toàn khu hạn chế, kể cả đường băng", "Sân đỗ (エプロン) và đường xe chạy", "Sân đỗ, đường vành đai, đường xe chạy", "Sân đỗ và đường vành đai"], "optsEn": ["Entire area including runways", "Apron and vehicle roads", "Apron, perimeter road, vehicle roads", "Apron and perimeter road"], "ans": 1, "expJa": "第一種地区は制限区域内全域、第二種地区はエプロン・場周道路・車両通路、第三種地区はエプロンと車両通路と区分されている。", "expVi": "Khu loại 1 là toàn bộ khu vực hạn chế, khu loại 2 là sân đỗ, đường vành đai và đường xe chạy, còn khu loại 3 là sân đỗ và đường xe chạy.", "expEn": "Class 1 is the whole restricted area, Class 2 is the apron, perimeter road and vehicle roads, and Class 3 is the apron and vehicle roads."},
  {"id": "S2A02", "topic": "s2_rules", "level": 2, "src": "SSW2テキスト 10-3-1 5. (p.118)", "qJa": "制限区域に立ち入る際、ビジター立入者IDカードを表示する位置として定められているのはどこか。", "qVi": "Khi vào khu vực hạn chế, thẻ ID khách tạm thời (ビジター立入者IDカード) phải đeo ở vị trí nào?", "qEn": "When entering the restricted area, where must a visitor ID card be displayed?", "optsJa": ["胸部", "右上腕部", "腰部", "左上腕部"], "optsVi": ["Ngực", "Bắp tay phải", "Thắt lưng", "Bắp tay trái"], "optsEn": ["Chest", "Right upper arm", "Waist", "Left upper arm"], "ans": 3, "expJa": "承認証等は外から容易に見えるよう表示する。標準IDカードは胸部、ビジター立入者や工事立入者の承認証は左上腕部とされている。", "expVi": "Giấy phép phải đeo sao cho dễ nhìn từ bên ngoài. Thẻ ID tiêu chuẩn đeo ở ngực, còn thẻ của khách tạm thời và người thi công đeo ở bắp tay trái.", "expEn": "Passes must be easily visible. The standard ID card goes on the chest, while visitor and construction passes go on the left upper arm."},
  {"id": "S2A03", "topic": "s2_rules", "level": 2, "src": "SSW2テキスト 10-3-1 10. (p.120)", "qJa": "制限区域内で1台の車両がけん引できる非自走車両の台数は、何台を越えてはならないか。", "qVi": "Trong khu vực hạn chế, số xe không tự hành (非自走車両) được kéo không được vượt quá bao nhiêu chiếc?", "qEn": "In the restricted area, the number of non-self-propelled vehicles towed must not exceed how many?", "optsJa": ["6台", "4台", "8台", "10台"], "optsVi": ["6 chiếc", "4 chiếc", "8 chiếc", "10 chiếc"], "optsEn": ["6", "4", "8", "10"], "ans": 0, "expJa": "積載制限の規定で、定員や規定積載量を越えてはならず、けん引できる非自走車両は6台を越えてはならないとされている。", "expVi": "Theo quy định về giới hạn chở, không được vượt quá số người và tải trọng quy định, và số xe không tự hành được kéo không được quá 6 chiếc.", "expEn": "The loading rule forbids exceeding seating and load limits, and the number of towed non-self-propelled vehicles must not exceed six."},
  {"id": "S2A04", "topic": "s2_rules", "level": 2, "src": "SSW2テキスト 10-3-1 11. (p.120)", "qJa": "原則として、地上走行中の航空機の後方何m以内を車両で走行してはならないか。", "qVi": "Về nguyên tắc, xe không được chạy trong phạm vi bao nhiêu mét phía sau tàu bay đang lăn trên mặt đất?", "qEn": "As a rule, vehicles must not drive within how many meters behind a taxiing aircraft?", "optsJa": ["30m", "50m", "100m", "200m"], "optsVi": ["30 m", "50 m", "100 m", "200 m"], "optsEn": ["30 m", "50 m", "100 m", "200 m"], "ans": 2, "expJa": "車両の操作及び走行の遵守事項として、地上を走行している航空機の後ろ100m以内は原則として走行してはならないと定められている。", "expVi": "Trong các điều phải tuân thủ khi vận hành xe, về nguyên tắc cấm chạy trong vòng 100 m phía sau tàu bay đang lăn.", "expEn": "Among the vehicle operating rules, driving within 100 m behind a taxiing aircraft is prohibited in principle."},
  {"id": "S2A05", "topic": "s2_rules", "level": 2, "src": "SSW2テキスト 10-3-1 13. (p.122)", "qJa": "制限区域内で、航空機の周辺30m以内（車両通路走行中を除く）を走行する場合の最高速度はどれか。", "qVi": "Trong khu vực hạn chế, tốc độ tối đa khi chạy trong phạm vi 30 m quanh tàu bay (trừ khi đang chạy trên đường xe chạy) là bao nhiêu?", "qEn": "In the restricted area, what is the speed limit within 30 m of an aircraft (except when on a vehicle road)?", "optsJa": ["10km/h以下", "15km/h以下", "20km/h以下", "30km/h以下"], "optsVi": ["Tối đa 10 km/h", "Tối đa 15 km/h", "Tối đa 20 km/h", "Tối đa 30 km/h"], "optsEn": ["10 km/h or less", "15 km/h or less", "20 km/h or less", "30 km/h or less"], "ans": 1, "expJa": "航空機の周辺30m以内は15km/h以下とされ、さらに航空機に向かって5m以内に近づいた時は10km/h以下とされている。", "expVi": "Trong vòng 30 m quanh tàu bay giới hạn 15 km/h, và khi tiến về phía tàu bay trong vòng 5 m thì giới hạn 10 km/h.", "expEn": "Within 30 m of an aircraft the limit is 15 km/h, and when approaching within 5 m of the aircraft it drops to 10 km/h."},
  {"id": "S2A06", "topic": "s2_rules", "level": 2, "src": "SSW2テキスト 10-3-1 12. (p.121)", "qJa": "霧や降雪などによる低視程時に制限区域で車両を運転する際の留意事項として、誤っているものはどれか。", "qVi": "Khi lái xe trong khu vực hạn chế lúc tầm nhìn kém do sương mù, tuyết…, lưu ý nào sau đây KHÔNG đúng?", "qEn": "Which is NOT correct as a point to observe when driving in the restricted area in low visibility such as fog or snow?", "optsJa": ["車両の立入りは必要最小限にする", "通常時よりも減速して走行する", "窓の汚れを除去し視界を保つ", "前照灯は上向きで点灯する"], "optsVi": ["Hạn chế xe vào ở mức tối thiểu", "Chạy chậm hơn so với bình thường", "Lau sạch kính xe để giữ tầm nhìn", "Bật đèn pha chiếu xa (hướng lên)"], "optsEn": ["Keep vehicle entry to a minimum", "Drive slower than usual", "Clean windows to keep a clear view", "Turn on headlights on high beam"], "ans": 3, "expJa": "低視程時は日中でも前照灯を点灯するが、点灯は下向きで行うとされている。立入りの最小化、減速、外部監視の強化、窓の清掃などが求められる。", "expVi": "Khi tầm nhìn kém phải bật đèn pha cả ban ngày nhưng phải chiếu gần (hướng xuống). Ngoài ra cần hạn chế xe vào, giảm tốc, tăng quan sát bên ngoài và lau kính.", "expEn": "In low visibility headlights must be on even in daytime, but on low beam. Minimizing entry, slowing down, closer lookout and clean windows are also required."},
  {"id": "S2A07", "topic": "s2_rules", "level": 2, "src": "SSW2テキスト 10-3-1 15. (p.124)", "qJa": "車両使用承認条件で、緊急車両以外の航空保安業務等に従事する車両の車体の塗装色はどれか。", "qVi": "Theo điều kiện cấp phép sử dụng xe, xe phục vụ nghiệp vụ an ninh hàng không (không phải xe khẩn cấp) phải sơn màu gì?", "qEn": "Under the vehicle use approval conditions, what color must vehicles in air navigation services, other than emergency vehicles, be painted?", "optsJa": ["黄色", "赤色", "黄緑色", "白色"], "optsVi": ["Màu vàng", "Màu đỏ", "Màu vàng chanh (xanh vàng)", "Màu trắng"], "optsEn": ["Yellow", "Red", "Yellow-green", "White"], "ans": 0, "expJa": "車体は航空機側から見分けやすい鮮やかな色とされ、緊急車両は赤色または黄緑色、それ以外の航空保安業務等の車両は黄色で塗装する。", "expVi": "Thân xe phải sơn màu nổi bật để tàu bay dễ nhận ra: xe khẩn cấp màu đỏ hoặc vàng chanh, còn xe nghiệp vụ an ninh hàng không khác màu vàng.", "expEn": "Vehicles must be painted a vivid color easily seen from aircraft: red or yellow-green for emergency vehicles and yellow for other air navigation service vehicles."},
  {"id": "S2A08", "topic": "s2_rules", "level": 2, "src": "SSW2テキスト 10-5 (p.128)", "qJa": "労働基準法第34条で、労働時間が6時間を超える場合に与えなければならない休憩時間はどれか。", "qVi": "Theo Điều 34 Luật Tiêu chuẩn Lao động (労働基準法), khi thời gian làm việc vượt quá 6 giờ thì phải cho nghỉ giải lao bao lâu?", "qEn": "Under Article 34 of the Labor Standards Act, what break must be given when working hours exceed 6 hours?", "optsJa": ["少なくとも30分", "少なくとも45分", "少なくとも1時間", "少なくとも15分"], "optsVi": ["Ít nhất 30 phút", "Ít nhất 45 phút", "Ít nhất 1 giờ", "Ít nhất 15 phút"], "optsEn": ["At least 30 minutes", "At least 45 minutes", "At least 1 hour", "At least 15 minutes"], "ans": 1, "expJa": "6時間を超える場合は45分以上、8時間を超える場合は1時間以上の休憩を労働時間の途中に与えることが義務付けられている。", "expVi": "Làm việc quá 6 giờ phải cho nghỉ ít nhất 45 phút, quá 8 giờ phải cho nghỉ ít nhất 1 giờ, và thời gian nghỉ phải nằm giữa giờ làm việc.", "expEn": "Over 6 hours requires at least 45 minutes, and over 8 hours at least 1 hour, given during working hours."},
  {"id": "S2P01", "topic": "s2_pax", "level": 2, "src": "SSW2テキストvol.2 1-2(1) (p.3)", "qJa": "国際線チェックインで、渡航先国の入国条件をリアルタイムで検索・確認するために使われるシステムとして、テキストが挙げているものはどれか。", "qVi": "Khi làm thủ tục chuyến quốc tế, hệ thống nào được giáo trình nêu ra để tra cứu theo thời gian thực điều kiện nhập cảnh của nước đến?", "qEn": "At international check-in, which system does the textbook name for real-time searching of the destination country's entry requirements?", "optsJa": ["WorldTracer（手荷物捜索システム）", "DCS（離発着管理システム）", "TIMATIC（国際運送情報システム）", "APIS（事前旅客情報システム）"], "optsVi": ["WorldTracer (hệ thống truy tìm hành lý)", "DCS (hệ thống quản lý cất/hạ cánh)", "TIMATIC (thông tin vận chuyển quốc tế)", "APIS (hệ thống thông tin hành khách trước)"], "optsEn": ["WorldTracer (baggage tracing system)", "DCS (departure control system)", "TIMATIC (travel information system)", "APIS (advance passenger info system)"], "ans": 2, "expJa": "テキストでは、渡航先国の入国条件はTIMATIC等で要件をリアルタイムに検索して入念に確認するとされている。WorldTracerは手荷物捜索、DCSは搭乗券発行などに使う。", "expVi": "Theo giáo trình, điều kiện nhập cảnh của nước đến được tra cứu theo thời gian thực bằng TIMATIC v.v. và kiểm tra kỹ. WorldTracer dùng để truy tìm hành lý, DCS dùng để in thẻ lên máy bay.", "expEn": "The textbook says entry requirements are checked carefully by real-time searches in TIMATIC or similar. WorldTracer is for baggage tracing and DCS is used to issue boarding passes."},
  {"id": "S2P02", "topic": "s2_pax", "level": 2, "src": "SSW2テキストvol.2 1-2(2) (p.4)", "qJa": "預け入れ手荷物を受け取る際、受託前からある破損が見つかった。テキストによる対応として正しいものはどれか。", "qVi": "Khi nhận hành lý ký gửi, phát hiện hư hỏng đã có từ trước khi nhận. Theo giáo trình, cách xử lý đúng là gì?", "qEn": "When accepting checked baggage, damage that existed before acceptance is found. According to the textbook, what is the correct action?", "optsJa": ["免責同意書へのサインを受け取る", "事故報告書（PIR）を作成し修理を手配する", "超過料金（EBG）を徴収してから受託する", "ゲートで受託手荷物への変更処理を行う"], "optsVi": ["Lấy chữ ký vào giấy miễn trách nhiệm", "Lập báo cáo sự cố (PIR) và sắp xếp sửa chữa", "Thu phí vượt mức (EBG) rồi mới nhận ký gửi", "Chuyển sang hành lý ký gửi tại cửa ra máy bay"], "optsEn": ["Have the passenger sign a Limited Release", "Prepare a PIR and arrange repair of the bag", "Collect an excess baggage charge, then accept it", "Process it as a gate check at the boarding gate"], "ans": 0, "expJa": "受け取り時は外観の破損を確認し、受託前からある破損については免責同意書（Limited Release）にサインをもらう。PIRは到着後の手荷物トラブル時に作成するものである。", "expVi": "Khi nhận hành lý phải kiểm tra hư hỏng bên ngoài; hư hỏng có sẵn từ trước thì cho khách ký giấy miễn trách nhiệm (Limited Release). PIR là báo cáo lập khi có sự cố hành lý lúc đến.", "expEn": "The outside of the bag is checked on acceptance, and for damage that was already there a Limited Release signature is obtained. A PIR is used for baggage problems on arrival."},
  {"id": "S2P03", "topic": "s2_pax", "level": 2, "src": "SSW2テキストvol.2 1-2(2) (p.4)", "qJa": "預け入れ手荷物で、1個あたりの重量の上限を超えている場合、テキストではどう対応するとされているか。", "qVi": "Với hành lý ký gửi vượt quá giới hạn cho mỗi kiện, giáo trình hướng dẫn xử lý thế nào?", "qEn": "If a checked bag exceeds the per-piece upper limit, what does the textbook say staff should do?", "optsJa": ["超過料金を徴収すればそのまま受託できる", "機内持ち込み手荷物として持ち込ませる", "貨物扱いに切り替えて別便で輸送する手続きをとる", "荷物の詰め直し（移し替え・分散）を依頼する"], "optsVi": ["Chỉ cần thu phí vượt mức là nhận ký gửi bình thường", "Cho khách mang lên máy bay làm hành lý xách tay", "Làm thủ tục gửi theo dạng hàng hóa trên chuyến khác", "Đề nghị khách đóng gói lại (chuyển, chia nhỏ)"], "optsEn": ["Accept it as is once an excess charge is collected", "Let the passenger carry it into the cabin instead", "Arrange to send it as cargo on another flight", "Ask the passenger to repack (move or split items)"], "ans": 3, "expJa": "無料手荷物許容量の超過時は超過料金（EBG）を徴収するが、1個あたりの上限を超える場合は荷物の詰め直し（移し替え・分散）を依頼すると書かれている。", "expVi": "Khi vượt hạn mức miễn cước thì thu phí EBG, nhưng nếu một kiện vượt giới hạn tối đa thì phải đề nghị khách sắp xếp lại (chuyển, chia nhỏ).", "expEn": "Exceeding the free allowance means an excess baggage charge, but a bag over the per-piece limit requires the passenger to repack by moving or splitting items."},
  {"id": "S2P04", "topic": "s2_pax", "level": 2, "src": "SSW2テキストvol.2 1-2(3) (p.5)", "qJa": "搭乗手続き、座席変更、マイレージ登録、タグ発行、領収書発行ができるセルフサービス端末はどれか。", "qVi": "Thiết bị tự phục vụ nào cho phép làm thủ tục, đổi ghế, đăng ký dặm bay, in thẻ hành lý và in hóa đơn?", "qEn": "Which self-service device lets passengers check in, change seats, register mileage, print tags and get receipts?", "optsJa": ["自動手荷物預け機（SBD）", "自動チェックイン機（CUSS）", "有人チェックインカウンター", "ゲートリーダー（搭乗スキャナー）"], "optsVi": ["Máy ký gửi hành lý tự động (SBD)", "Máy làm thủ tục tự động (CUSS)", "Quầy thủ tục có nhân viên", "Đầu đọc tại cửa (máy quét)"], "optsEn": ["Self bag drop machine (SBD)", "Self check-in kiosk (CUSS)", "Staffed check-in counter", "Gate reader (boarding scanner)"], "ans": 1, "expJa": "テキストでは自動チェックイン機（CUSS）の機能として搭乗手続き・座席変更・マイレージ登録・タグ発行・領収書発行が挙げられている。SBDは旅客自身がベルトコンベアに荷物を乗せて預け入れを完了する機械である。", "expVi": "Giáo trình liệt kê các chức năng của máy CUSS: làm thủ tục, đổi ghế, đăng ký dặm, in thẻ, in hóa đơn. SBD là máy để khách tự đặt hành lý lên băng chuyền hoàn tất ký gửi.", "expEn": "The textbook lists check-in, seat changes, mileage registration, tag printing and receipts as CUSS functions. An SBD is where passengers put bags on the belt themselves to finish bag drop."},
  {"id": "S2P05", "topic": "s2_pax", "level": 2, "src": "SSW2テキストvol.2 1-2(4)(c) (p.6)", "qJa": "ゲートでスキャナーがない場合やシステムエラー時の対応として、テキストの内容と誤っているものはどれか。", "qVi": "Về cách xử lý tại cửa khi không có máy quét hoặc hệ thống bị lỗi, điều nào KHÔNG đúng với giáo trình?", "qEn": "Which of the following is NOT correct as a response at the gate when there is no scanner or the system fails?", "optsJa": ["搭乗券の半券を切り取り、最後にシステム数と照合する", "紙の旅客名簿で一人ずつ消し込み、人数確認をする", "システムが復旧するまで搭乗案内を中止して待つ", "車椅子や子供連れの旅客を優先的に機内へ誘導する"], "optsVi": ["Xé cuống thẻ lên máy bay, cuối cùng đối chiếu với số trên hệ thống", "Gạch tên từng người trên danh sách giấy và đếm số khách", "Dừng mời lên máy bay và chờ đến khi hệ thống phục hồi", "Ưu tiên dẫn khách xe lăn, khách có con nhỏ lên máy bay"], "optsEn": ["Tear off boarding pass stubs and check them against system numbers", "Tick off each name on a paper manifest and do a headcount", "Stop boarding and wait until the system is restored", "Guide wheelchair users and families with children on first"], "ans": 2, "expJa": "テキストでは、スキャナーがない場合やシステムエラー時は半券回収（もぎり）、名簿照合とヘッドカウント、特別介助者の優先誘導を行うとされ、搭乗を中止して待つという記述はない。", "expVi": "Giáo trình nêu: thu cuống vé (もぎり), đối chiếu danh sách và đếm đầu người (ヘッドカウント), ưu tiên dẫn khách cần hỗ trợ; không có nội dung dừng lên máy bay để chờ.", "expEn": "The textbook lists collecting stubs, checking a paper manifest with a headcount, and boarding passengers needing assistance first; it does not say to stop boarding and wait."},
  {"id": "S2P06", "topic": "s2_pax", "level": 2, "src": "SSW2テキストvol.2 1-2(4)(d) (p.7)", "qJa": "施設内を巡回しても未搭乗者が見つからない場合に実施する手続きはどれか。", "qVi": "Nếu đã đi tìm trong nhà ga mà vẫn không thấy khách chưa lên máy bay, thủ tục nào được thực hiện?", "qEn": "If a passenger who has not boarded cannot be found after searching the terminal, which procedure is carried out?", "optsJa": ["預け荷物を機内から降ろすオフロード", "出発時刻を遅らせて捜索を続ける", "搭乗拒否として処理する判断", "代替便への振り替え（Rebook）"], "optsVi": ["Dỡ hành lý ký gửi của khách khỏi máy bay (オフロード)", "Lùi giờ khởi hành để tiếp tục tìm kiếm", "Quyết định từ chối cho lên máy bay (Denied Boarding)", "Chuyển khách sang chuyến bay thay thế (Rebook)"], "optsEn": ["Offloading their checked bags from the aircraft", "Delaying departure to keep searching for them", "Making a denied boarding decision", "Rebooking the passenger on another flight"], "ans": 0, "expJa": "未搭乗者を巡回して捜索し、見つからない場合は預け荷物を機内から降ろすオフロード（Baggage Offload）を行うと書かれている。これは保安規定に伴う荷物の取り降ろしである。", "expVi": "Giáo trình ghi: đi tìm khách chưa lên máy bay, nếu không thấy thì làm thủ tục オフロード, tức dỡ hành lý ký gửi khỏi máy bay theo quy định an ninh.", "expEn": "Staff search the facility, and if the passenger is not found, the checked bags are taken off the aircraft (Baggage Offload), as required by security rules."},
  {"id": "S2P07", "topic": "s2_pax", "level": 2, "src": "SSW2テキストvol.2 1-3 (p.7)", "qJa": "到着時の手荷物トラブル（未着・紛失・破損）対応で作成する「PIR」とは何か。", "qVi": "Khi xử lý sự cố hành lý lúc đến (chưa tới, thất lạc, hư hỏng), \"PIR\" được lập là gì?", "qEn": "In handling baggage problems on arrival (missing, lost or damaged), what is the \"PIR\" that is prepared?", "optsJa": ["旅客の予約記録", "事前の旅客情報データ", "特別サービスの要求", "手荷物の事故報告書"], "optsVi": ["Hồ sơ đặt chỗ của hành khách", "Thông tin hành khách gửi trước", "Yêu cầu dịch vụ đặc biệt", "Báo cáo sự cố hành lý"], "optsEn": ["Passenger booking record", "Advance passenger information", "Special service request", "Baggage incident report"], "ans": 3, "expJa": "ロストバゲージや破損の際は、捜索システムWorldTracerへの入力とPIR（Property Irregularity Report:事故報告書）の作成、修理・配送手続きを行う。", "expVi": "Khi hành lý thất lạc hoặc hư hỏng, nhân viên nhập vào WorldTracer, lập PIR (báo cáo sự cố) và làm thủ tục sửa chữa, giao hành lý thay khách.", "expEn": "For lost or damaged baggage, staff enter the case in WorldTracer, prepare a PIR (Property Irregularity Report) and arrange repair or delivery."},
  {"id": "S2P08", "topic": "s2_pax", "level": 2, "src": "SSW2テキストvol.2 1-4 (p.8)", "qJa": "乗り継ぎ案内で把握すべき「MCT」の意味として正しいものはどれか。", "qVi": "Trong hướng dẫn nối chuyến, \"MCT\" cần nắm có nghĩa là gì?", "qEn": "In transfer guidance, what does \"MCT\" mean?", "optsJa": ["最大乗り継ぎ回数", "最低接続時間", "搭乗ゲート締切時刻", "手荷物返却所要時間"], "optsVi": ["Số lần nối chuyến tối đa", "Thời gian nối chuyến tối thiểu", "Giờ đóng cửa lên máy bay", "Thời gian trả hành lý cần thiết"], "optsEn": ["Maximum number of connections", "Minimum connecting time", "Boarding gate closing time", "Baggage return time"], "ans": 1, "expJa": "MCTは最低接続時間で、移動距離、手続きの種類（国内/国際）、航空会社の組み合わせにより設定された時間を守れているか確認する。", "expVi": "MCT là thời gian nối chuyến tối thiểu; cần kiểm tra khách có kịp thời gian được đặt theo khoảng cách di chuyển, loại thủ tục (nội địa/quốc tế) và tổ hợp hãng bay hay không.", "expEn": "MCT is the minimum connecting time, set by walking distance, type of procedure (domestic or international) and airline combination; staff check that it can be met."},
  {"id": "S2P09", "topic": "s2_pax", "level": 2, "src": "SSW2テキストvol.2 1-5 (p.8)", "qJa": "スペシャルアシスタンスの対象者のうち、「UM（アナカン）」とはどのような旅客か。", "qVi": "Trong các đối tượng hỗ trợ đặc biệt, \"UM (アナカン)\" là hành khách như thế nào?", "qEn": "Among special assistance passengers, what kind of passenger is a \"UM\"?", "optsJa": ["座席まで車椅子が必要な旅客", "出産予定日が近い妊娠中の旅客", "一人で旅行する子供", "視覚や聴覚に障がいのある旅客"], "optsVi": ["Khách cần xe lăn đến tận ghế", "Khách mang thai gần ngày dự sinh", "Trẻ em đi máy bay một mình", "Khách khiếm thị hoặc khiếm thính"], "optsEn": ["A passenger needing a wheelchair to the seat", "A pregnant passenger near the due date", "A child travelling on their own", "A passenger with sight or hearing loss"], "ans": 2, "expJa": "テキストでは主な対象の一つとして、子供一人旅（UM:Unaccompanied Minor / アナカン）が挙げられている。車椅子利用はWCHR等の区分で示される。", "expVi": "Giáo trình nêu trẻ em đi một mình (UM: Unaccompanied Minor / アナカン) là một trong các đối tượng chính. Khách dùng xe lăn được phân loại bằng mã WCHR v.v.", "expEn": "The textbook lists children travelling alone (UM: Unaccompanied Minor) as a main group. Wheelchair users are classified with codes such as WCHR."},
  {"id": "S2P10", "topic": "s2_pax", "level": 2, "src": "SSW2テキストvol.2 1-5(3) (p.9)", "qJa": "メディカル対応で確認する「MEDIF」について、テキストの説明に合うものはどれか。", "qVi": "Về \"MEDIF\" được kiểm tra trong hỗ trợ y tế, mô tả nào phù hợp với giáo trình?", "qEn": "Regarding the \"MEDIF\" checked for medical cases, which description matches the textbook?", "optsJa": ["英文の診断書兼同意書で、内容と有効期限を確認", "携帯用酸素濃縮器の機内使用を記録する用紙", "車椅子のバッテリー種類を申告する危険物書類", "ストレッチャー用の座席ブロックを依頼する予約票"], "optsVi": ["Giấy chẩn đoán tiếng Anh kiêm đồng ý; xem nội dung, hạn", "Phiếu ghi nhận việc sử dụng máy tạo oxy cầm tay trên máy bay", "Giấy khai báo hàng nguy hiểm về loại pin của xe lăn", "Phiếu đặt chỗ yêu cầu khóa ghế để đặt cáng"], "optsEn": ["An English medical certificate; check its content and expiry", "A form recording in-flight use of a portable oxygen concentrator", "A dangerous goods form declaring a wheelchair battery type", "A booking slip requesting seats blocked for a stretcher"], "ans": 0, "expJa": "MEDIFは英文診断書（診断書兼同意書）で、その内容と有効期限を確認し、航空旅行が可能かどうかを照合する。", "expVi": "MEDIF là giấy chẩn đoán tiếng Anh (kiêm giấy đồng ý); nhân viên kiểm tra nội dung, thời hạn hiệu lực và đối chiếu xem khách có đủ điều kiện đi máy bay không.", "expEn": "A MEDIF is an English medical certificate combined with consent; staff check its content and validity to confirm whether air travel is allowed."},
  {"id": "S2P11", "topic": "s2_pax", "level": 2, "src": "SSW2テキストvol.2 1-7(1) (p.10)", "qJa": "APIS（パスポート・ビザ事前審査）の説明として正しいものはどれか。", "qVi": "Mô tả nào đúng về APIS (thẩm tra trước hộ chiếu, thị thực)?", "qEn": "Which statement correctly describes APIS (advance passport and visa screening)?", "optsJa": ["到着地で入国を拒否された旅客の送還便を手配する", "保安区域内で職員のIDを確認し、不審者を警戒する", "旅客が到着後に税関で申告書を電子的に提出する", "搭乗手続き時に航空会社が旅客データを当局へ送る"], "optsVi": ["Sắp xếp chuyến bay đưa về cho khách bị từ chối nhập cảnh tại nơi đến", "Kiểm tra thẻ nhân viên trong khu an ninh và cảnh giác người lạ", "Khách nộp tờ khai hải quan điện tử sau khi đến nơi", "Hãng bay gửi dữ liệu khách cho cơ quan nước đến lúc làm thủ tục"], "optsEn": ["Arranging a return flight for a passenger refused entry on arrival", "Checking staff IDs in security areas and watching for suspects", "Passengers submit customs declarations online after arriving", "Airline sends traveller data to the destination at check-in"], "ans": 3, "expJa": "APISでは、航空会社が搭乗手続きの際に渡航者データを送り、渡航先国の出入国管理当局と事前データ（Advance Passenger Information）を共有して承認を得る。入国拒否旅客への対応はINAD対応である。", "expVi": "Với APIS, hãng bay gửi dữ liệu hành khách khi làm thủ tục, chia sẻ thông tin trước (Advance Passenger Information) với cơ quan xuất nhập cảnh nước đến và nhận chấp thuận. Xử lý khách bị từ chối nhập cảnh là INAD.", "expEn": "Under APIS the airline transmits traveller data during check-in and shares Advance Passenger Information with the destination's immigration authority to get approval. Handling refused passengers is INAD work."},
  {"id": "S2P12", "topic": "s2_pax", "level": 2, "src": "SSW2テキストvol.2 1-13 (p.12)", "qJa": "CAから機内準備完了（Cabin Ready）を受領し、ボーディング開始を指示するのは誰の業務か。", "qVi": "Nhận thông báo chuẩn bị khoang khách xong (Cabin Ready) từ tiếp viên và ra lệnh bắt đầu cho khách lên là nhiệm vụ của ai?", "qEn": "Whose duty is it to receive Cabin Ready from the cabin crew and give the instruction to start boarding?", "optsJa": ["カウンター責任者（CL）", "ゲート責任者（GC）", "ランプハンドリング作業責任者", "ロードコントロール担当者"], "optsVi": ["Trưởng quầy thủ tục (CL / カウンターリーダー)", "Trưởng phụ trách cửa ra máy bay (GC)", "Người phụ trách tác nghiệp sân đỗ (ランプ)", "Nhân viên kiểm soát tải (ロードコントロール)"], "optsEn": ["The counter leader (CL)", "The gate controller (GC)", "The ramp handling supervisor", "The load control staff member"], "ans": 1, "expJa": "ゲート責任者（GC）は搭乗口オペレーションを統括し、搭乗案内のタイミングを判断して、CAからCabin Readyを受領した上でボーディング開始を指示する。", "expVi": "Trưởng cửa (GC) điều hành toàn bộ hoạt động tại cửa, quyết định thời điểm mời lên máy bay, nhận Cabin Ready từ tiếp viên rồi ra lệnh bắt đầu boarding.", "expEn": "The gate controller oversees gate operations, decides boarding timing, and after receiving Cabin Ready from the cabin crew instructs boarding to begin."},
  {"id": "S2F01", "topic": "s2_fuel", "level": 2, "src": "SSW2テキストvol.2 2-1 (p.13)", "qJa": "航空機が超長距離や特別な飛行以外で燃料を満タンにしない理由として、テキストが挙げているものはどれか。", "qVi": "Theo giáo trình, vì sao máy bay không đổ đầy nhiên liệu, trừ chuyến siêu dài hoặc chuyến đặc biệt?", "qEn": "According to the textbook, why are aircraft not filled to full tanks except for very long or special flights?", "optsJa": ["搭載した燃料の重量でエンジンの消費燃料も増えるため", "燃料を満タンにすると給油時間が長くなりすぎてしまうため", "燃料タンク内の燃料が劣化しやすくなるため", "消防法で機体の燃料搭載量が制限されているため"], "optsVi": ["Vì trọng lượng nhiên liệu làm động cơ tiêu hao nhiều hơn", "Vì đổ đầy sẽ khiến thời gian tiếp nhiên liệu quá lâu", "Vì nhiên liệu trong bình dễ bị biến chất hơn", "Vì Luật Phòng cháy giới hạn lượng nhiên liệu nạp vào máy bay"], "optsEn": ["Because carrying more fuel weight raises engine fuel burn", "Because filling up would make refuelling take far too long", "Because the fuel in the tanks would deteriorate more easily", "Because the Fire Service Act limits aircraft fuel loads"], "ans": 0, "expJa": "航空機は搭載した燃料の重量によりエンジンの消費燃料も増加するため、通常は満タンにしない。そこで航空会社が指示した必要量を各タンクに配分して搭載する。", "expVi": "Vì trọng lượng nhiên liệu nạp vào làm động cơ tiêu hao nhiều nhiên liệu hơn, nên máy bay thường không đổ đầy, mà nạp đúng lượng hãng chỉ định, chia cho từng bình.", "expEn": "The weight of the fuel itself raises engine fuel consumption, so aircraft are not normally filled up; the amount ordered by the airline is loaded and distributed among the tanks."},
  {"id": "S2F02", "topic": "s2_fuel", "level": 2, "src": "SSW2テキストvol.2 2-1 (p.13)", "qJa": "アンダー・ウイング給油の説明として正しいものはどれか。", "qVi": "Mô tả nào đúng về tiếp nhiên liệu dưới cánh (アンダー・ウイング給油)?", "qEn": "Which is a correct description of under-wing refuelling?", "optsJa": ["主翼の上部の給油口から燃料を注ぎ入れる方式", "ドラム缶の燃料を直接機体タンクへ流し込む方式", "主翼の下部から圧力によって燃料を搭載する方式", "尾翼のタンクにだけ専用ホースで搭載する方式"], "optsVi": ["Phương thức rót nhiên liệu qua miệng nạp phía trên cánh chính", "Phương thức đổ thẳng nhiên liệu từ thùng phuy vào bình máy bay", "Phương thức nạp nhiên liệu từ phía dưới cánh chính bằng áp lực", "Phương thức chỉ nạp vào bình ở đuôi bằng ống chuyên dụng"], "optsEn": ["Fuel is poured in through a filler on top of the main wing", "Fuel is poured straight from drums into the aircraft tanks", "Fuel is loaded under pressure from below the main wing", "Fuel is loaded only into the tail tank with a special hose"], "ans": 2, "expJa": "テキストでは、主翼の上部から搭載するオーバー・ウイング給油と、下部から圧力で搭載するアンダー・ウイング給油があると説明されている。", "expVi": "Giáo trình giải thích có hai cách: nạp từ phía trên cánh (オーバー・ウイング給油) và nạp bằng áp lực từ phía dưới cánh (アンダー・ウイング給油).", "expEn": "The textbook describes over-wing refuelling from the top of the wing and under-wing refuelling, where fuel is loaded under pressure from below."},
  {"id": "S2F03", "topic": "s2_fuel", "level": 2, "src": "SSW2テキストvol.2 2-2 B (p.14)", "qJa": "航空ガソリンの規格について、現在国内で使われているものはどれか。", "qVi": "Về tiêu chuẩn xăng hàng không, loại nào hiện đang được dùng trong nước Nhật?", "qEn": "Which aviation gasoline grade is currently used in Japan?", "optsJa": ["「80/87」の1種類のみ", "「100」の1種類のみ", "「100/130」と「115/145」", "「91/98」と「100」"], "optsVi": ["Chỉ một loại \"80/87\"", "Chỉ một loại \"100\"", "Loại \"100/130\" và \"115/145\"", "Loại \"91/98\" và \"100\""], "optsEn": ["Only grade \"80/87\"", "Only grade \"100\"", "Grades \"100/130\" and \"115/145\"", "Grades \"91/98\" and \"100\""], "ans": 1, "expJa": "ガソリンの規格は以前は80/87、91/98、100/130、115/145などがあったが、現在国内では100のみとされている。", "expVi": "Trước đây có các loại 80/87, 91/98, 100/130, 115/145…, nhưng hiện nay ở Nhật chỉ còn loại 100.", "expEn": "Grades such as 80/87, 91/98, 100/130 and 115/145 existed in the past, but only grade 100 is used in Japan today."},
  {"id": "S2F04", "topic": "s2_fuel", "level": 2, "src": "SSW2テキストvol.2 2-2 B (p.14)", "qJa": "航空ガソリンの規格「100/130」のうち、分母の「130」は何を示しているか。", "qVi": "Trong tiêu chuẩn xăng hàng không \"100/130\", mẫu số \"130\" biểu thị điều gì?", "qEn": "In the aviation gasoline grade \"100/130\", what does the denominator \"130\" show?", "optsJa": ["航空法（巡航状態）で測ったアンチノック性の値", "燃料に加える四エチル鉛の添加量", "燃料1リットルあたりの発熱量", "過給法（離陸状態）で測ったアンチノック性の値"], "optsVi": ["Giá trị chống kích nổ đo theo phương pháp hàng không (khi bay bằng)", "Lượng chì tetraethyl được thêm vào nhiên liệu", "Nhiệt lượng tỏa ra trên mỗi lít nhiên liệu", "Giá trị chống kích nổ đo theo phương pháp tăng áp (khi cất cánh)"], "optsEn": ["Anti-knock value measured by the aviation method (cruise)", "The amount of tetraethyl lead added to the fuel", "The heat value produced per litre of fuel", "Anti-knock value by the supercharge method (take-off)"], "ans": 3, "expJa": "100/130の分子は航空法（巡航状態）の値、分母は過給法（離陸状態）の値を示す。同じ燃料でも過給法で測ったほうがアンチノック性は大きくなる。", "expVi": "Trong 100/130, tử số là giá trị đo theo phương pháp hàng không (bay bằng), mẫu số là giá trị theo phương pháp tăng áp (cất cánh). Cùng loại xăng, đo theo phương pháp tăng áp cho tính chống kích nổ cao hơn.", "expEn": "In 100/130 the numerator is the aviation-method (cruise) value and the denominator is the supercharge-method (take-off) value; the same fuel shows higher anti-knock quality by the supercharge method."},
  {"id": "S2F05", "topic": "s2_fuel", "level": 2, "src": "SSW2テキストvol.2 2-2 C (p.16)", "qJa": "民間機に使われるジェット燃料Jet A-1とJet Bの違いとして正しいものはどれか。", "qVi": "Điểm khác nhau đúng giữa nhiên liệu phản lực Jet A-1 và Jet B dùng cho máy bay dân dụng là gì?", "qEn": "Which correctly states the difference between Jet A-1 and Jet B used in civil aircraft?", "optsJa": ["Jet A-1は灯油留分のみ、Jet Bは灯油留分と重質ナフサがほぼ同量", "Jet A-1は重質ナフサのみ、Jet Bは灯油留分に四エチル鉛を加えたもの", "Jet A-1は軍用機専用、Jet Bは民間旅客機専用として区別されている", "Jet A-1は航空ガソリンと灯油の混合、Jet Bは灯油留分のみで構成"], "optsVi": ["Jet A-1 chỉ có dầu hỏa; Jet B pha dầu hỏa và naphtha nặng gần bằng nhau", "Jet A-1 chỉ gồm naphtha nặng; Jet B là dầu hỏa có pha thêm chì tetraethyl", "Jet A-1 chỉ dùng cho máy bay quân sự, Jet B chỉ cho máy bay chở khách", "Jet A-1 trộn xăng hàng không với dầu hỏa; Jet B chỉ gồm phân đoạn dầu hỏa"], "optsEn": ["Jet A-1: kerosene only; Jet B: kerosene and heavy naphtha about half each", "Jet A-1 is heavy naphtha only; Jet B is kerosene with tetraethyl lead", "Jet A-1 is only for military aircraft; Jet B is only for civil airliners", "Jet A-1 mixes avgas with kerosene; Jet B consists of kerosene only"], "ans": 0, "expJa": "テキストによると、Jet A-1は灯油留分のみで構成され、Jet Bは灯油留分と重質ナフサ（ガソリン）がほぼ同量ずつ混合されている。", "expVi": "Theo giáo trình, Jet A-1 chỉ gồm phân đoạn dầu hỏa, còn Jet B là hỗn hợp dầu hỏa và naphtha nặng (xăng) với tỷ lệ gần bằng nhau.", "expEn": "The textbook says Jet A-1 consists only of the kerosene fraction, while Jet B mixes kerosene and heavy naphtha (gasoline) in roughly equal amounts."},
  {"id": "S2F06", "topic": "s2_fuel", "level": 2, "src": "SSW2テキストvol.2 2-3 (p.15)", "qJa": "燃料搭載量（燃料オーダー）の算出の考え方として、テキストにある各社おおむね共通の式はどれか。", "qVi": "Về cách tính lượng nhiên liệu nạp (燃料オーダー), công thức gần như chung của các hãng nêu trong giáo trình là gì?", "qEn": "Which formula does the textbook give as broadly common to airlines for calculating the fuel order?", "optsJa": ["目的空港＋予備燃料＋タキシング燃料", "最大搭載量－到着時の残存燃料", "目的空港＋代替空港＋予備燃料", "出発空港＋目的空港＋旅客数補正"], "optsVi": ["Sân bay đích + nhiên liệu dự phòng + nhiên liệu lăn bánh", "Lượng nạp tối đa − nhiên liệu còn lại khi đến", "Sân bay đích + sân bay dự bị + nhiên liệu dự phòng", "Sân bay đi + sân bay đích + hiệu chỉnh số khách"], "optsEn": ["Destination + reserve fuel + taxi fuel", "Maximum capacity minus fuel remaining on arrival", "Destination + alternate airport + reserve fuel", "Departure + destination + passenger adjustment"], "ans": 2, "expJa": "燃料オーダーは航空法に基づく各社の運航基準で、天候・旅客数・貨物・代替空港等を考慮して算出され、おおむね「目的空港＋代替空港＋予備燃料」である。代替空港は目的空港が悪天候等で着陸できない場合のものである。", "expVi": "Lượng nhiên liệu được tính theo tiêu chuẩn khai thác của từng hãng dựa trên Luật Hàng không, xét thời tiết, số khách, hàng hóa, sân bay dự bị…; về cơ bản là \"sân bay đích + sân bay dự bị + nhiên liệu dự phòng\".", "expEn": "The fuel order is calculated under each airline's operating standards based on the Civil Aeronautics Act, considering weather, passengers, cargo and alternates; broadly it is destination plus alternate plus reserve fuel."},
  {"id": "S2F07", "topic": "s2_fuel", "level": 2, "src": "SSW2テキストvol.2 2-4 A (p.16)", "qJa": "フューエラー方式について、消防法で制限されている車両1台あたりのタンク容量の最大値はどれか。", "qVi": "Với phương thức xe tiếp nhiên liệu (フューエラー), dung tích bồn tối đa của một xe theo Luật Phòng cháy là bao nhiêu?", "qEn": "For the fueller method, what is the maximum tank capacity per vehicle under the Fire Service Act?", "optsJa": ["20kℓ", "30kℓ", "40kℓ", "50kℓ"], "optsVi": ["20 kℓ", "30 kℓ", "40 kℓ", "50 kℓ"], "optsEn": ["20 kL", "30 kL", "40 kL", "50 kL"], "ans": 1, "expJa": "消防法により車両1台のタンク容量は最大30kℓに制限されているため、多量の燃料を給油するには複数台と時間が必要になる。", "expVi": "Theo Luật Phòng cháy, mỗi xe chỉ được có bồn tối đa 30 kℓ, nên khi cần nạp nhiều nhiên liệu phải dùng nhiều xe và mất thời gian.", "expEn": "The Fire Service Act limits each vehicle's tank to 30 kL, so loading a large amount of fuel needs several vehicles and more time."},
  {"id": "S2F08", "topic": "s2_fuel", "level": 2, "src": "SSW2テキストvol.2 2-4 B (p.18)", "qJa": "ハイドラント方式で、燃料を航空機へ圧送する役割を担うものはどれか。", "qVi": "Trong phương thức hydrant (ハイドラント方式), bộ phận nào đảm nhận việc bơm đẩy nhiên liệu vào máy bay?", "qEn": "In the hydrant method, what pumps the fuel into the aircraft under pressure?", "optsJa": ["サービサーに搭載された送油ポンプ", "航空機側の燃料ブースターポンプ", "スポットごとの可搬式ポンプ車", "給油施設に設置された固定ポンプ"], "optsVi": ["Máy bơm nhiên liệu gắn trên xe servicer", "Bơm tăng áp nhiên liệu phía máy bay", "Xe bơm di động đặt sẵn tại từng vị trí đỗ", "Máy bơm cố định của cơ sở cấp nhiên liệu"], "optsEn": ["A delivery pump mounted on the servicer", "The aircraft's own fuel booster pump", "A mobile pump truck placed at each spot", "The fixed pump at the fuelling facility"], "ans": 3, "expJa": "ハイドラント方式は、貯油タンクから地下配管でスポットまで結び、ハイドラント・バルブと航空機をサービサーで接続し、給油施設の固定ポンプで圧送する。サービサーは流量計・フィルター・ホース等を備えた給油車である。", "expVi": "Phương thức hydrant nối bồn chứa đến từng vị trí đỗ bằng ống ngầm, dùng xe servicer nối van hydrant với máy bay, rồi bơm đẩy bằng máy bơm cố định của cơ sở cấp nhiên liệu. Servicer chỉ có đồng hồ lưu lượng, bộ lọc, ống…", "expEn": "In the hydrant method, underground pipes run from storage tanks to each spot, a servicer links the hydrant valve to the aircraft, and the facility's fixed pump pushes the fuel. A servicer carries a flow meter, filters and hoses."},
  {"id": "S2F09", "topic": "s2_fuel", "level": 2, "src": "SSW2テキストvol.2 2-5 B (p.18-19)", "qJa": "ハイドラント方式の燃料搭載作業で、静電気除去用アースを設置した直後に行う作業はどれか。", "qVi": "Trong quy trình nạp nhiên liệu bằng phương thức hydrant, ngay sau khi lắp dây tiếp đất khử tĩnh điện thì làm bước nào?", "qEn": "In the hydrant-method fuelling procedure, which step comes right after setting up the static grounding?", "optsJa": ["インテーク・ユニット取り付け（ピット⇔サービサー）", "デリバリー・ユニット取り付け（サービサー⇔航空機）", "危険区域表示の設置（セーフティー・コーン等）", "航空会社整備士と搭載量を相互に確認する"], "optsVi": ["Lắp bộ intake (hố hydrant ⇔ xe servicer)", "Lắp bộ delivery (xe servicer ⇔ máy bay)", "Đặt biển báo khu vực nguy hiểm (cọc an toàn…)", "Xác nhận chéo lượng nạp với thợ máy của hãng"], "optsEn": ["Connect the intake unit (hydrant pit–servicer)", "Connect the delivery unit (servicer to aircraft)", "Set out danger zone markers (safety cones)", "Cross-check the fuel amount with the mechanic"], "ans": 0, "expJa": "ハイドラント方式の手順は(3)危険区域表示設置、(4)アース設置、(5)インテーク・ユニット取り付け、(6)アクセス・ドア・オープン、(7)デリバリー・ユニット取り付けの順である。", "expVi": "Quy trình hydrant: (3) đặt biển khu nguy hiểm, (4) lắp tiếp đất, (5) lắp bộ intake, (6) mở cửa tiếp cận, (7) lắp bộ delivery.", "expEn": "The hydrant sequence is (3) danger zone markers, (4) static grounding, (5) intake unit, (6) open the access door, (7) delivery unit."},
  {"id": "S2F10", "topic": "s2_fuel", "level": 2, "src": "SSW2テキストvol.2 2-6 (p.21-22)", "qJa": "燃料搭載作業者に必要な公的資格のうち、危険物を取り扱うために必要とされているものはどれか。", "qVi": "Trong các chứng chỉ công cần cho người nạp nhiên liệu, chứng chỉ nào cần để xử lý hàng nguy hiểm?", "qEn": "Among the public qualifications for fuelling staff, which one is required for handling hazardous materials?", "optsJa": ["制限区域内車両運転資格", "危険物取扱者乙種第4類免状", "フューエリング・ステーション操作資格", "ワンマン給油作業者資格"], "optsVi": ["Chứng chỉ lái xe trong khu vực hạn chế", "Giấy phép xử lý hàng nguy hiểm Otsu loại 4", "Chứng chỉ vận hành trạm nạp nhiên liệu", "Chứng chỉ người nạp nhiên liệu làm một mình"], "optsEn": ["Restricted area vehicle driving permit", "Hazardous Materials Officer (Otsu, Type 4)", "Fuelling station operation qualification", "Qualification as a one-man fuelling operator"], "ans": 1, "expJa": "公的資格は自動車運転免許証、制限区域内車両運転資格、危険物取扱者乙種第4類免状で、危険物を取り扱うためには乙種第4類が必要である。フューエリング・ステーション操作資格は航空会社資格、ワンマン給油作業者は元売り会社資格である。", "expVi": "Chứng chỉ công gồm bằng lái ô tô, chứng chỉ lái xe trong khu hạn chế và giấy phép 危険物取扱者乙種第4類; giấy phép này cần để xử lý hàng nguy hiểm. Chứng chỉ vận hành trạm nạp là của hãng bay, còn người nạp một người là chứng chỉ của công ty phân phối dầu.", "expEn": "The public qualifications are a driving licence, a restricted area driving permit and the Class Otsu Type 4 hazardous materials licence, which is needed to handle hazardous materials. Station operation is an airline qualification; one-man fuelling is an oil company qualification."},
];
